        0
      } else if (dmap(12) > 1) {
        0
      } else if (dmap.exists(_ > 2)) {
        0
      } else {
        val patterns: Array[List[Int]] = dmap.zipWithIndex.flatMap { case (count, d) =>
          if (count == 0) {
            List()
          } else if (count == 1) {
            if (d == 12) {
              List(List(d))
            } else {
              List(List(d, 24 - d))
            }
          } else {
            List(List(d), List(24 - d))
          }
        }

        def minS(ds: List[Int]): Int = {
          val dsSorted = ds.toArray.sorted

          var minS = Int.MaxValue
          for(i <- dsSorted.indices) {
            minS = Math.min(minS, (dsSorted((i + 1) % dsSorted.length) - dsSorted(i) + 24) % 24)
          }

          minS
        }

        def findMaxS: Int = {
          def inner(ds: List[Int], patterns: List[List[Int]]): Int = {
            patterns match {
              case p :: rest =>
                p match {
                  case p1 :: p2 :: Nil =>
                    Math.max(
                      inner(p1 :: ds, rest),
                      inner(p2 :: ds, rest)
                    )
                  case p1 :: Nil =>
                    inner(p1 :: ds, rest)
                  case _ =>
                    throw new Error()
                }
              case Nil =>
                minS(ds)
            }
          }
          inner(0 :: Nil, patterns.toList)
        }

        findMaxS
      }
    )

    out.flush()
  }
}

