int e[24];
int dfs(int t) {
    if (t == 0) {
        if (v[0] >= 2) {
            return 0;
        }
        e[0] = v[0];
        return dfs(t+1);
    }

    if (t == 12) {
        if (v[12] >= 2) {
            return 0;
        }

        e[12] = v[12];

        int ret = 1 << 28;
        for (int t = 0; t < 24; ++t) {
            for (int u = t+1; u < 24; ++u) {
                if (e[t] > 0 && e[u] > 0) {
                    ret = min(ret, min(abs(t-u), 24-abs(t-u)));
                }
            }
        }

        return ret;
    }

    if (v[t] == 2) {
        e[t] = 1; e[24-t] = 1;
        return dfs(t+1);
    } else if (v[t] == 1) {
        e[t] = 1; e[24-t] = 0;
        int v1 = dfs(t+1);
        e[t] = 0; e[24-t] = 1;
        int v2 = dfs(t+1);
        return max(v1, v2);
    }
    e[t] = e[24-t] = 0;
    return dfs(t+1);
}

