}

vector<ll> tsort(Graph G)
{
    ll N = G.size();
    vector<ll> in(N);
    for (auto &&edges : G)
    {
        for (auto &&edge : edges)
        {
            in[edge]++;
        }
    }

    queue<int> que;

    for (int i = 0; i < N; i++)
    {
        if (in[i] == 0)
        {
            que.push(i);
        }
    }
    int cnt = 0;
    vector<ll> ans;
    while (!que.empty())
    {
        int v = que.front();
        que.pop();
        ans.push_back(v);
        for (auto &&next : G[v])
        {

            in[next]--;
            if (in[next] == 0)
            {
                que.push(next);
            }
        }
    }
    return ans;
}


void solve(long long N, std::vector<long long> D){
    vector<ll> st(N+1,-1);
    st[0] = 0;
    RSORT(D);
    st[1] = D[0];

    for (int i = 1; i < N; i++)
    {
        ll one = D[i];
        ll two = 24 - D[i];
        if(abs(st[i]-one)> abs(st[i]-two)){
            st[i+1] = one;
        }else{
            st[i+1] = two;
        }
    }
    ll ans = INF;
    for (int i = 0; i < N+1; i++)
    {
        for (int j = i+1; j < N+1; j++)
        {
            ans = min(ans,abs(st[i]-st[j]));
        }

    }
    cout << ans << endl;


}

