                    else jj = (24-j)%24;
                    if((i>>k)%2) kk=k;
                    else kk = (24-k)%24;
                    m = min(m, min(abs(jj-kk), 24-abs(jj-kk)));
                }
            }
        }
        //cout << m << endl;

        s = max(s, m);        
    }    
    cout << s << endl;


