using namespace std;

ll calc(vector<ll>& time)
{
  ll res = INF;
  for (ll i = 0; i < 24; ++i) {
    if (time.at(i) > 1) {
      return 0;
    }
    if (time.at(i) == 1) {
      for (ll j = 1; j <= 12; ++j) {
        if (time.at((i + j) % 24) == 1) {
          res = min(res, j);
          break;
        }
        ll temp = i - j;
        if (temp < 0) {
          temp += 24;
        }
        if (time.at(temp) == 1) {
          res = min(res, j);
          break;
        }
      }
    }
  }
  return res;
}

