    time.at(D.at(i)) += 1;
  }

  ll ans = 0;
  for (ll i = 0; i < (1 << 11); ++i) {
    vector<ll> temp = time;
    for (ll j = 0; j < 11; ++j) {
      if (i & (1 << j)) {
        if (temp.at(j + 1) >= 1) {
          temp.at(j + 1) -= 1;
          temp.at(23 - j) += 1;
        }
      }
    }
    ans = max(ans, calc(temp));
  }
  cout << ans << endl;
}

