void dfs(ll idx) {
  if (idx == n) {
    ll lst = 0;
    ll v = INF;
    REP(i, 24) {
      if (t[i]) {
        chmin(v, i - lst);
        chmin(v, 24 - i + lst);
        lst = i;
      }
    }
    chmin(v, 24 - lst);
    chmin(v, lst);

    chmax(ans, v);
  }

  if (d[idx] == 0) {
    return;
  }

  if (t[d[idx]] == 0) {
    t[d[idx]] = 1;
    dfs(idx + 1);
    t[d[idx]] = 0;
  }

  if (t[24 - d[idx]] == 0) {
    t[24 - d[idx]] = 1;
    dfs(idx + 1);
    t[24 - d[idx]] = 0;
  }
}

