void addM(long long &a, long long b) {
    a += b;
    if (a >= MOD) a -= MOD;
}

void mulM(long long &a, long long b) {
    a = ((a%MOD)*(b%MOD))%MOD ;
}

// a^b mod M
long myPow(long a,long b,int M) {
    long ret = 1;
    long tmp = a;
    while(b>0) {
        if((b&1)==1) ret = (ret * tmp) % M;
        tmp = (tmp * tmp) % M;
        b = b>>1;
    }
    return ret;
}

 // nCk mod M
int nCk(int n,int k,int M) {
    long ret = 1;
    int mi = min(k, n-k);
    for(int i=1;i<=mi;i++) {
        ret = (ret * myPow(i,M-2,M)) % M;
    }
    for(int i=n-mi+1;i<=n;i++) {
        ret = (ret * i) % M;
    }
    return (int)ret;
};

vector<pair<long long, long long> > prime_factorize(long long n) {
    vector<pair<long long, long long> > res;
    for (long long p = 2; p * p <= n; ++p) {
        if (n % p != 0) continue;
        int num = 0;
        while (n % p == 0) { ++num; n /= p; }
        res.push_back(make_pair(p, num));
    }
    if (n != 1) res.push_back(make_pair(n, 1));
    return res;
}

int main() {
    vector<int> time(13, 0);
    time[0]++;

    int N;
    cin >> N;
    REP(i, N){
        int t;
        cin >> t;
        time[t]++;
    }

    if(time[0] >= 2 || time[12] >= 2){
        cout << 0 << endl;
        return 0;
    }
    REP(i, 13){
        if(time[i] >= 3){
            cout << 0 << endl;
            return 0;
        }
    }

    int ans = 0;
    REP(i, 1 << 11){
        vector<int> res;

        res.push_back(0);
        if(time[12] == 1) res.push_back(12);

        for(int j = 1; j <= 11; j++){
            if(time[j] == 0) continue;
            if(time[j] == 2){
                res.push_back(j);
                res.push_back(24 - j);
            } else {
