    bool ok = true;
    // 1から11が1だと不定
    //不定なものについてbit全探索
    kakutei[0] = true;
    if(cnt[12] >= 1) kakutei[12] = true;
    if(cnt[0] >= 2 || cnt[12] >= 2) ok = false;
    for(int i = 1; i <= 11; i++){
        if(cnt[i] >= 3) ok = false;
        else if(cnt[i] == 2) kakutei[i] = true;
        else if(cnt[i] == 1) futei_num.push_back(i);
    }

