int N, ans;
int taken[100];
vector<long long> D;

void dfs(int v) {
    // debug(v);
    // debug(D[v]);
    if (v == N) {
        int last = 0;
        int x = 24;
        for (int i = 1; i < 24; i++) {
            if (taken[i] > 0) {
                chmin(x, i - last);
                last = i;
            }
        }
        chmin(x, 24 - last);
        chmax(ans, x);
        return;
    }
    if (!taken[D[v]]) {
        taken[D[v]]++;
        dfs(v + 1);
        taken[D[v]]--;
    }
    int other = (24 - D[v]) % 24;
    if (other != D[v] and !taken[other]) {
        taken[other]++;
        dfs(v + 1);
        taken[other]--;
    }
}

