		D[d]++;
	}

	int ans = 0;
	for (int bit = 0b0; bit < (1 << 13); bit++) {

		vector<int> time{ 0 };
		time.reserve(N);
		for (int i = 0; i < 13; i++) {
			for (int j = 0; j < D[i]; j++) {
				if (!(bit & (1 << i) ^ (j & 1))) time.emplace_back(i);
