			}
		}

		DMP(time);

		int s = INF;
		for (int i = 0; i <= N; i++) {
			for (int j = i + 1; j <= N; j++) {
				chmin(s, min(abs(time[i] - time[j]), 24 - abs(time[j] - time[i])));
			}
		}
		chmax(ans, s);

	}

	cout << ans << "\n";

	return 0;
