const int maxn = 55;
int n, ans, d[maxn], res[maxn], tmp[maxn];

void dfs(int i) {
	if (i == n) {
		copy(res, res + n, tmp);
		sort(tmp, tmp + n);
		int mx = 24;
		for (int i = 0, j = n - 1; i < n; j = i++) {
			mx = min(mx, min(abs(res[i] - res[j]), 24 - abs(res[i] - res[j])));
		}
        ans = max(ans, mx);
		return;
	}
	for (int j = -1; j <= 1; j += 2) {
		res[i] = d[i] * j;
		dfs(i + 1);
		if (d[i] == 0 || d[i] == 12) {
			break;
		}
	}
}

