int ans, n;

void go (int in, vector < int > vec) {
    if (in == n) {
        int dif = inf;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int q1 = vec[i];
                int q2 = vec[j];
                if (q1 > q2) swap(q1, q2);
                q2 -= q1;
                q1 = 0;
                dif = min(dif, min(q2, 24 - q2));
            }
        }
        ans = max(ans, dif);
        return ;
    }
    vec.pb(d[in]);
    go(in + 1, vec);
    vec.pp();

    vec.pb(24 - d[in]);
    go(in + 1, vec);
    vec.pp();
}

