struct Problem{
    int n;
    vector<int > d;
    Problem(LL n):n(n),d(n){};
    int mindist(vector<int> &s){
        int ret=30,prev=0;
        for(auto && x: s){
            DBG(ret,x)
            ret=min(ret,x-prev);
            prev=x;
        }
        ret = min(ret,24-prev);
        return ret;
    }

    void solve(){
        if(n>=24){
            cout << 0 <<"\n";
            return;
        }
        for(int i=0; i<n; ++i){
            cin >> d[i];
        }
        int ans=0;
