int check(vector<int> t){
  int res = 24;
  sort(t.begin(), t.end());
  t.erase(unique(t.begin(), t.end()), t.end());

  for(int i=0;i<t.size();++i){
    res = min(abs(t[i]-t[(i+1)%t.size()]), res);
  }

  if (res>12) return 0;
  return res;
}

