int main(){
  ll N; cin >> N;
  vector<ll> cnt(13,0), D(N+1);
  D[0] = 0; cnt[0]++; //高橋くん
  REP(i,N){
    cin >> D[i+1];
    cnt[D[i+1]]++;
  }
  //0が2人以上いれば,必ずs=0
  if(cnt[0]>=2){
    cout << 0 << endl;
    return 0;
  }
  //D(>=1)が同じ人が3人以上いれば，必ずs=0
  FOR(i,1,13){
    if(cnt[i]>=3){
      cout << 0 << endl;
      return 0;
    }
  }
  //D=0はいない&&同じDを取る人は2人以下
  ll U = (1<<N);
  ll ans = 0;
  REP(i,U){
    vector<ll> T(N+1);
    T[0] = 0;
    REP(j,N){
      if(i&(1<<j)) T[j+1] = D[j+1];
      else  T[j+1] = (24 - D[j+1])%24;
    }
    ll mini = 1e18;
    REP(i,N) FOR(j,i,N+1){
      ll a = min(T[i],T[j]);
      ll b = max(T[i],T[j]);
      b -= a;
      mini = min(mini, min(b,24-b));
    }
    ans = max(ans,mini);
  }
  cout << ans << endl;
}

