set<int> aloneNum;

int dfs(int t, int S){
    if(t > 12){
        int retVal =12;
        vector<int> selcted;
        for(int i=0;i<24;i++){
            if(S &(1<<i)){
                selcted.push_back(i);
            }
        }
        selcted.push_back(24);
        // cerr << "cal" << endl;
        for(int i=0;i<selcted.size();i++){
            // cerr << selcted[i] << endl;
            if(i==0){
                continue;
            }
            int temp = selcted[i]-selcted[i-1];
            retVal = min(retVal,min(temp,24-temp));
        }
        return retVal;
    }
    if(aloneNum.find(t) != aloneNum.end()){
        return max(dfs(t+1,S|(1<<t)),dfs(t+1,S|(1<<(24-t))));
    }
    return dfs(t+1,S);

}

