                return 0;
            }
        }else{
            if(a.second >= 2){
                cout<<0<<endl;
                return 0;
            }
        }
    }
    if(n + 1 >= 23){
        cout<<0<<endl;
        return 0;
    }
    mp[0]++;
    vector<int> vvv(24);
    bool f = true;
    for(auto a : mp){
        if(a.second == 2){
            vvv[a.first] = 2;
            vvv[24 - a.first - 1] = 2;
        }else if(a.second == 1){
            if(a.first == 0){
                vvv[a.first] = 2;
            }else{
                if(f){
                    vvv[a.first] = 2;
                }else{
