  if (c[idx]==1) {
    st.push(idx);
    create_vec(idx+1, st);
    st.pop();
    if (idx < 12) {
      st.push(24-idx);
      create_vec(idx+1, st);
    }
  } else if (c[idx]==2) { // 同じものに関しては最終的に0になり、候補外 
    st.push(idx);
    st.push(24-idx);
    create_vec(idx+1, st);
  }
  else create_vec(idx+1, st);
}

