    lvec inv(m);
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < m; i++)
    {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;

    }
}

ll pow_mod(ll a, ll n)
{
    ll x = 1;
    while (n > 0)
    {
        if (n & 1)
        {
            x = x * a % MOD;
        }
        a = a * a % MOD;
        n >>= 1;
    }
    return x;
}


ll COM(int n, int k, const lvec &fac, const lvec &finv)
{
    if (n < k)
        return 0;
    if (n < 0 || k < 0)
        return 0;
    return (fac[n] * (finv[k] * finv[n - k] % MOD)) % MOD;
}

ll modinv(ll a, ll m)
{
    ll b = m, u = 1, v = 0;
    while (b)
    {
        ll t = a / b;
        a -= t * b;
        swap(a, b);
        u -= t * v;
        swap(u, v);
    }
    u %= m;
    if (u < 0)
        u += m;
    return u;
}

typedef map<ll, double> Prob;

void calc(Prob &firsts, Prob &seconds, Prob &thirds){
    vector< pair<double, lvec> > pr;
    for (auto fv: firsts){        
        for (auto sv: seconds){
            for (auto tv: thirds){
                if(fv.first == sv.first || sv.first == tv.first || fv.first == tv.first) continue;
                lvec s(3);
                s[0] = (fv.first);
                s[1] = (sv.first);
                s[2] = (tv.first);
                double p = fv.second*sv.second*tv.second;
                pr.pb( pair<double, lvec >(p, s));
            }
        }
    }

    sort(pr.begin(), pr.end(), greater<pair<double, lvec> >());
    for (auto v: pr){
