    auto cond = [&](ll di) -> bool {
        return m[di] == 2 && di == 0 && di == 12;
    };
    vector<ll> ddbl;
    copy_if(ALL_OF(d), back_inserter(ddbl), cond);
    d.erase(remove_if(ALL_OF(d), cond), d.end());
    REP(i, ddbl.size()) {
        if (ddbl[i] && i % 2) {
            ddbl[i] = (24 - ddbl[i]) % 24;
        }
