int diff_time(int a, int b){
    int ret = abs(a-b);
    int d = 24-a-b;
    ret = max(ret,min(d,24-d));
    return ret;
}

int solve(){
    map<int,int> cnt;
    for(auto d:D) cnt[d]++;
    int ans = 0;
    vector<int> time,timeD;;
    for(auto p:cnt){
        if(p.second==1) time.push_back(p.first);
        else if(p.second==2){
            if(p.first==0){
                cout << 0 << endl;
                return 0;
            }
            timeD.push_back(p.first);
            timeD.push_back(24-p.first);
        }
        else if(p.second>=3){
            cout << 0 << endl;
            return 0;
        }        
    }
    int T = time.size();
    if(N>1){
        for (int bit = 0; bit < (1<<T); bit++)
        {
            vector<int> time_mod;
            for (int i = 0; i < T; i++)
            {
                if((bit>>i)&1) time_mod.push_back(24-time[i]);
                else time_mod.push_back(time[i]);
            }
            int tmp_ans = 24;
            for(auto timed:timeD) time_mod.push_back(timed);
            for (int i = 0; i < (int)time_mod.size(); i++)
            {
                for (int j = i+1; j < (int)time_mod.size(); j++)
                {
                    int d = abs(time_mod[i]-time_mod[j]);
                    tmp_ans = min(tmp_ans,min(d,24-d));
                }

            }
            for(auto d:D) tmp_ans=min(tmp_ans,d);
            DBG(tmp_ans)
            ans = max(ans,tmp_ans);
        }
    }

    cout << ans << endl;
    return 0;
}   

int main()
{
    input();
    solve();
    return 0;
}

