int main(){
  int n;
  int d[60], t[24] = {};

  scanf("%d",&n);

  for(int i=0;i<n;i++){
    scanf("%d",d+i);
    t[d[i]]++;
  }
  t[0]++;

  for(int i=1;i<12;i++){
    if(t[i] >= 2){
      t[24-i] ++;
      t[i]--;
    }
  }

  for(int i=0;i<24;i++){
    if(t[i] >= 2){
      puts("0");
      return 0;
    }
  }

  int ANS = 0;

  for(int i=0;i<(1<<11);i++){
    int memo[24];

    for(int j=0;j<24;j++)
      memo[j] = t[j];

    for(int j=1;j<12;j++){
      if(i & (1 << (j-1)) && t[j] == 1 && t[24-j] == 0){
        memo[j] = 0;
        memo[24-j] = 1;
      }
    }

    int ans = 25;

    for(int j=0;j<24;j++){
      for(int k=0;k<24;k++){
        if(memo[j] && memo[k] && j != k){
          ans = min(ans, abs(j-k));
        }
      }
    }

    ANS = max(ANS, ans);
  }

  printf("%d\n",ANS);


  return 0;
}

