ll beki(ll a, ll b) {
	ll tmp = 1;
	REP(i, b) tmp *= a;
	return tmp;
}

int main() {

	int N;
	int D[20];
	int Dtmp[20];
	bool bit[20] = {};
	int ans = 0;
	int clock[20] = {};

	cin >> N;
	D[0] = 0;
	clock[0]++;
	int k = 1;
	REP(i, N) {

		int tmp;
		cin >> tmp;
		if (clock[tmp] < 2) {
			D[k] = tmp;
			clock[D[k]]++;
			k++;
		}
		else {
			cout << 0 << endl;
		}
	}
	N = k;

	//bit全探索
	//まず0ならDi,1なら24-Diをつっこむ
	REP(i, beki(2, N)) {
		//これで2^N回ループ
		int tmp = i;
		REP(j, N) {
			bit[j] = tmp;
			tmp /= 2;
		}
		int sum = 0;
		//これでbit[0]~[N - 1]までにビットたってるか入った
		REP(j, N) {
			if (bit[j]) Dtmp[j] = D[j];
			else Dtmp[j] = 24 - D[j];
		}
		sort(Dtmp, Dtmp + N);
		int anstmp = INF;
		REP(j, N - 1) {
			anstmp = min(Dtmp[j + 1] - Dtmp[j], anstmp);
		}
		anstmp = min(Dtmp[0] + 24 - Dtmp[N - 1], anstmp);
		ans = max(anstmp, ans);
	}
	cout << ans << endl;
}

