    int n;
    cin >> n;
    vector<int> d(n);
    rep(i, n) cin >> d[i];

    vector<int> cnt(24, 0);
    rep(i, n) ++cnt[d[i]];
    if (cnt[0]) {
        cout << "0\n";
        return;
    }
    vector<bool> iru(24, false);
    iru[0] = true;
    vector<int> vec;
    rep(i, 24) {
        if (cnt[i] == 1) {
            vec.push_back(i);
        }
        if (cnt[i] == 2) {
            if (i == 12) {
                cout << "0\n";
                return;
            }
            iru[i] = iru[24 - i] = true;
        }
        if (cnt[i] >= 3) {
            cout << "0\n";
            return;
        }
    }

    if (!sz(vec)) {
        int res = inf;
        rep(i, 24) rep(j, 24) {
            if (i != j && iru[i] && iru[j]) chmin(res, min(abs(i - j), 24 - abs(i - j)));
        }
        cout << res << "\n";
        return;
    }
    int ans = 0;
    rep(bit, 1 << sz(vec)) {
        auto iru_ = iru;
        rep(i, sz(vec)) {
            if ((bit >> i) & 1) iru_[vec[i]] = true;
            else iru_[24 - vec[i]] = true;
        }
        int res = inf;
        rep(i, 24) rep(j, 24) {
            if (i != j && iru_[i] && iru_[j]) chmin(res, min(abs(i - j), 24 - abs(i - j)));
        }
        chmax(ans, res);
    }

    cout << ans << "\n";
    return;
}

