            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    auto t = abs(d[i] - d[j]);
                    ret = min(ret, min(t, 24 - t));
                }
            }
            return ret;
        };

        for (int bit = 0; bit < (1<<n); bit++) {
            ans = max(ans, f(bit));
        }
        cout << ans << endl;
    }
