        for(int i=0;i<table.size();i++){
            for(int j=i+1;j<table.size();j++){
                if(table[i] && table[j]){
                    res=min(res,min(j-i,24-(j-i)));
                }
            }
        }
        return res;
    }
    if(cnt[idx]==0) return dfs(idx+1,cnt,table);
    else if(cnt[idx]==1){
        table[idx]=true;
