int minTime(vector<int> &arr) {
  int time = 24;
  vector<int> c;
  rep(i, arr.size()) if (arr[i] >= 1) c.push_back(i);

  rep(i, c.size() - 1) time = min(time, c[i + 1] - c[i]);
  time = min(time, 24 - c.back());
  return time;
}

