	while(num > 0)
	{
		res += num&1;
		num>>=1;
	}
	return res!=N+1;
}

array<bool, ALLt> make_all(vector<ll> D)
{
	array<bool, ALLt> res;
	REP(i, ALLt)res[i] = false;
	ll siz = D.size();
	REP(i, (1 << siz))
	{
		ll tmp = 1;
		REP(j, siz)
		{
			bool isBef = ((i >> j) & 1) == 1;
			ll hour = isBef ? D[j] : 24 - D[j];

			ll flag = (1 << hour);
			if(flag&tmp==1)goto stop;
			tmp|=flag;
		}
		res[tmp] = true;
		stop:;
	}
	return res;
}

ll judge(ll num)
{
	if(duplicate(num))return 0;
	//REP(i,24) cerr<<(num>>i&1)<<" ";
	//cerr<<endl<<endl;
	ll res = 24;
	REP(i, 24)FOR(j, i + 1, 24) if(((num >> i) & 1) && ((num >> j) & 1))
		res = min((ll)res, min(j - i, 24 - (j - i)));
	return res;
}

