const int MAXN = 55;
int N;
bool occ[24];
int D[MAXN];
int curr = 100;
int best = 0;

void dfs(int v) {
    if (curr <= best) return;
    if (v == N) {
        best = max(best, curr);
        return;
    }
    vector<int> pos = {D[v]};
    if (D[v] != 0) pos.push_back(24-D[v]);
    for (int p : pos) {
        if (occ[p]) continue;
        int curr_prec = curr;
        for (int i = 0; i < 24; i++) {
            int d = abs(i-p);
            if (occ[i]) curr = min(curr, min(d, 24-d));
        }
        occ[p] = 1;
        dfs(v+1);
        occ[p] = 0;
        curr = curr_prec;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0); // Remove in problems with online queries!

    cin >> N;
    for (int i = 0; i < N; i++) cin >> D[i];
    if (N > 23) {
        cout << 0 << "\n";
        return 0;
    }
    occ[0] = 1;
    dfs(0);
    cout << best << "\n";
}

