int main(){
	int n;
	cin >> n;
	int t[n];
	REP(i, n) cin >> t[i];
	if(n >= 24){
		cout << 0 << endl;
		return 0;
	}
	int d[24];
	int ans = 0;
	REP(i, 1<<n){
		d[0] = 1;
		fill(d+1, d+24, 0);
		vector<int> listt;
		REP(j, n){
			int bit = (i>>j)%2;
			if(bit){
				int time = t[j];
				if(d[time]==0){
					d[time] = 1;
					listt.pb(time);
				}
				else break;
			}
			else{
				int time = 24-t[j];
				if(d[time]==0){
					d[time] = 1;
					listt.pb(time);
				}
				else break;
			}
		}
		if(listt.size()!=n) continue;
		else{
			int c = 24;
			listt.pb(0);
			listt.pb(24);
			sort(ALL(listt));
			REP(i, listt.size()-1){
				c = min({c, listt[i+1]-listt[i], 24-listt[i+1]+listt[i]});
			}
			ans = max(ans, c);
		}
	}
	cout << ans << endl;
	return 0;
}

