void find(int x,int y){
	if(x==13){
		ans=max(ans,y);
		return;
	}
	if(t[x]==1){
		int d=y;
		for(int i=24-x-1;i>0;i--){
			if(s[i]==1){
				d=min(d,24-x-i);
				break;
			}
		}
		for(int i=24-x+1;i<24;i++){
			if(s[i]==1){
				d=min(d,i+x-24);
				break;
			}
		}
		s[24-x]=1;
		find(x+1,d);
		s[24-x]=0;
		d=y;
		for(int i=x-1;i>0;i--){
			if(s[i]==1){
				d=min(d,x-i);
				break;
			}
		}
		for(int i=x+1;i<24;i++){
			if(s[i]==1){
				d=min(d,i-x);
				break;
			}
		}
		s[x]=1;
		find(x+1,d);
		d=y;
		s[x]=0;
	}
	else find(x+1,y);
	return;
}
