#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define REP(i,n) for (ll i = 0; i < (n); ++i)

ll dist(ll x, ll y){
    return min(abs(x - y), 24 - abs(x - y));
}

void solve(long long N, std::vector<long long> D){
    D.push_back(0); // add takahashi
    vector<array<ll, 4>> tmp;
    REP(i, D.size()){
        for(ll j = i + 1; j < D.size(); ++j){
            ll t1 = dist(D.at(i), D.at(j));;
            ll t2 = dist(D.at(i), 24 - D.at(j));
            if(t1 < t2){
                tmp.push_back({t1, i, j, 0});
            }else if(t1 > t2){
                tmp.push_back({t2, i, j, 1});
            }
        }
    }
    sort(tmp.begin(), tmp.end());
    vector<ll> dir(D.size(), -1);
    for(auto a : tmp){
        const ll i = a.at(1);
        const ll j = a.at(2);
        const bool equal = a.at(3) != 0;

        if(equal){
            if(dir.at(i) == -1 && dir.at(j) == -1){
                dir.at(i) = 0;
                dir.at(j) = 0;
            }else if(dir.at(i) != -1 && dir.at(j) == -1){
                dir.at(j) = dir.at(i);
            }else if(dir.at(i) == -1 && dir.at(j) != -1){
                dir.at(i) = dir.at(j);
            }
        }else{
            if(dir.at(i) == -1 && dir.at(j) == -1){
                dir.at(i) = 0;
                dir.at(j) = 1;
            }else if(dir.at(i) != -1 && dir.at(j) == -1){
                dir.at(j) = 1 - dir.at(i);
            }else if(dir.at(i) == -1 && dir.at(j) != -1){
                dir.at(i) = 1 - dir.at(j);
            }
        }
    }

    REP(i, dir.size()){
        if(dir.at(i) == -1){
            dir.at(i) = 0;
        }
    }

    ll ans = 24;
    REP(i, D.size()){
        for(ll j = i + 1; j < D.size(); ++j){
            if(dir.at(i) == dir.at(j)){
                ans = min(ans, dist(D.at(i), D.at(j)));
            }else{
                ans = min(ans, dist(D.at(i), 24 - D.at(j)));
            }
        }
    }
    cout << ans << endl;
}

