int N;
int D[55];
int seq[55];
int val[55];
int num[55];
int res=0;

bool cmp(int aa, int bb)
{
	if(val[aa]<val[bb])
		return true;
	else
		return false;
}

int srch(int dep)
{
	if(dep==N+1)
		return 50;
	int i = seq[dep];
	int mn;
	int tmp;
	if(num[i]==-1 && num[i+1]==-1){
		num[i] = D[i];
		num[i+1] = 24-D[i+1];
		mn = num[i+1]-num[i];
		if(mn<0)
			mn = -mn;
		if(mn>=12)
			mn = 24-mn;
		tmp = srch(dep+1);
		if(mn > tmp)
			mn = tmp;
		int tmn = mn;
		num[i] = 24-D[i];
		num[i+1] = D[i+1];
		mn = num[i+1]-num[i];
		if(mn<0)
			mn = -mn;
		if(mn>=12)
			mn = 24-mn;
		tmp = srch(dep+1);
		if(mn > tmp)
			mn = tmp;
		if(tmn < mn)
			mn = tmn;
		num[i] = -1;
		num[i+1] = -1;
	}
	else if(num[i]==-1){
		if(num[i+1]>=12)
			num[i] = D[i];
		else
			num[i] = 24-D[i];
		mn = num[i+1]-num[i];
		if(mn<0)
			mn = -mn;
		if(mn>=12)
			mn = 24-mn;
		tmp = srch(dep+1);
		if(mn > tmp)
			mn = tmp;
		num[i] = -1;//
	}
	else if(num[i+1]==-1){
		if(num[i]>=12)
			num[i+1] = D[i+1];
		else
			num[i+1] = 24-D[i+1];
		mn = num[i+1]-num[i];
		if(mn<0)
			mn = -mn;
		if(mn>=12)
			mn = 24-mn;
		tmp = srch(dep+1);
		if(mn > tmp)
			mn = tmp;
		num[i+1] = -1;
	}
	else{
		mn = num[i+1]-num[i];
		if(mn<0)
			mn = -mn;
		if(mn>=12)
			mn = 24-mn;
		tmp = srch(dep+1);
		if(mn > tmp)
			mn = tmp;
	}
	if(mn < val[i])
		mn = val[i];
	return mn;
}

void solve()
{
	int i;
	D[N] = 0;
	sort(D, D+N+1);
	for(i=0; i<N; i++)
		seq[i] = i;
	for(i=0; i<N; i++)
		val[i] = D[i+1]-D[i];
	sort(seq, seq+N, cmp);
	for(i=0; i<N+1; i++)
		num[i] = -1;
	res = srch(0);
	printf("%d\n", res);
}

int main()
{
	int i;
	scanf("%d", &N);
	for(i=0; i<N; i++)
		scanf("%d", &D[i]);
	solve();
	return 0;
}

