    vector<int> cnt;
    Problem(LL n):n(n),cnt(13){};
    int mindist(vector<int> &s){
        int ret=30,prev=0;
        for(auto && x: s){
            DBG(ret,x)
            ret=min(ret,x-prev);
            prev=x;
        }
        ret = min(ret,24-prev);
        return ret;
