int main() {
  int n;
  cin>>n;
  map<int, int> m_d;
  ++m_d[0];
  for (int i=0; i<n; i++) {
    int di;
    cin>>di;
    ++m_d[di];
  }
  vector<int> d1, d2;
  for (auto x: m_d) {
    if (x.second > 2) {
      cout<<0<<endl;
      return 0;
    } else if (x.second == 2) {
      d2.push_back(x.first);
      d2.push_back(24 - x.first);
    } else {
      d1.push_back(x.first);
    }
  }
  int ans = 0;
  int len1 = d1.size();
  int len2 = d2.size();
  int mask = 1 << len1;
  int max_s = 0;
  for (int i=0; i<mask; i++) {
    int t[len1+len2];
    for (int j=0; j<len1; j++) {
      if ((i >> j) & 1) {
        t[j] = d1[j];
      } else {
        t[j] = 24 - d1[j];
      }
    }
    for (int j=0; j<len2; j++) {
      t[j+len1] = d2[j];
    }
    int min_d = 24;
    for (int j=0; j<len1+len2; j++) {
      for (int k=0; k<len1+len2; k++) {
        if (j == k) {
          continue;
        }
        min_d = min(min(abs(t[k]-t[j]), 24-abs(t[k]-t[j])), min_d);
      }
    }
    max_s = max(min_d, max_s);
  }
  cout<<max_s<<endl;
}

#include <iostream>
#include <algorithm>

#define N 60

int arr[N], tmp[N];

int main()
{
	int n; scanf("%d", &n);
	for(int i = 0; i < n; ++i) scanf("%d", arr + i);
	std::sort(arr, arr + n);
	std::fill(tmp, tmp + N, -1);
	std::copy(arr, arr + n, tmp);

	{
		int nn = 0;
		for(int i = 0; i < n; )
		{
			int j = i;
			int cur = tmp[i];
			while(tmp[j] == cur) j ++;
			j -= i;
			i += j;
			j = std::min(j, 2);
			while(j --) arr[nn ++] = cur;
		}
		n = nn;
	}
	for(int i = 0; i < n; ++i)
		arr[(n << 1) - 1 - i] = 24 - arr[i];

	const int u = 1 << n;
	int ans = 0;
	for(int k = 0; k < u; ++k)
	{
		int last = 0, dis;
		int cur = 0x7fffffff;
		for(int i = 0; i < n; ++i)
		{
			if((k >> i) & 1)
			{
				dis = std::abs(arr[i] - last);
				cur = std::min(cur, std::min(dis, 24 - dis));
				last = arr[i];
			}
		}
		for(int i = n - 1; i >= 0; --i)
		{
			if(((~k) >> i) & 1)
			{
				dis = std::abs(arr[(n << 1) - 1 - i] - last);
				cur = std::min(cur, std::min(dis, 24 - dis));
				last = arr[(n << 1) - 1 - i];
			}
		}

		ans = std::max(ans, cur);
	}

	printf("%d\n", ans);
	return 0;
}

