				tmp = min(tmp, a[d] - a[i]);	
				tmp = min(tmp, 24 - a[d] + a[i]);
			}
			else {
				tmp = min(tmp, a[i] - a[d]);
				tmp = min(tmp, 24 - a[i] + a[d]); 
			} 
		}
