                    used[pred & (1 << (i - 1)) ? i : 24 - i] = true;
                }
            }
        }
        repeat (i, 24) if (used[i]) {
            repeat (j, i) if (used[j]) {
                setmin(s, min(abs(i - j), 24 - abs(i - j)));
            }
        }
        setmax(max_s, s);
    }
    // output
    printf("%d\n", max_s);
    return 0;
}

