LL N;

LL ans = 0LL;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N;
	VI a(N);
	VI cnt(13, 0);

	FOR(i, 0, N) {
		cin >> a[i];
		cnt[a[i]]++;
	}
	cnt[0]++;
	FOR(i, 0, 13) {
		if (cnt[i] > 2) {
			cout << 0 << endl;
			return 0;
		}
	}

	if (cnt[0] > 1 || cnt[12] > 1) {
		cout << 0 << endl;
		return 0;
	}
	VI base(24, false);
	base[0] = true;
	if (cnt[12] == 1) {
		base[12] = true;
	}
	FOR(i, 0, 13) {
		if (cnt[i] == 2) {
			base[i] = base[24 - i] = true;
		}
	}
	ans = 0;
	FOR(i, 0, (1 << 11)) {
		VI used(48,0);
		FOR(i, 0, 24) {
			used[i] = base[i];
		}
		FOR(j, 0, 11) {
			if (cnt[j + 1] != 1) continue;
			if ((i >> j) & 1) {
				used[j + 1] = true;
			}
			else {
				used[24 - (j + 1)] = true;
			}
		}
		FOR(j, 0, 24) used[j + 24] = used[j];
		int l = 0;
		int tans = INF;
		FOR(r, 1, 48) {// 2周
			if (used[r]) {
				int t = min(r - l, 24 - (r - l));
				tans = min(tans, t);
				l = r;
			}
		}
		ans = max(ans, (LL)tans);
	}
	cout << ans << endl;


	return 0;
}

