struct MyMain {
	int N = in;
	ints D = in(N);
	ints counts;

	void Run() {
		counts.resize(13);
		counts[0]++;
		REP(i, N) {
			int d = D[i];
			counts[d]++;
		}

		ints used(25);
		int ans = Calc(used, 0);
		out << ans;
	}

	int Calc(ints& used, int t) {
		if (t > 12) {
			int minDist = 100;
			int before = -1;
			REP(i, 25) {
				if (used[i]) {
					if (before >= 0) {
						int d = i - before;
						chmin(minDist, d);
						before = i;
					}
					else {
						before = i;
					}
				}
			}
			return minDist;
		}

		int count = counts[t];

		if (count >= 3) {
			return 0;
		}
		else if (count == 2) {
			int a = t;
			int b = 24 - t;

			if (a == b) {
				return 0;
			}
			if (t == 0) {
				return 0;
			}

			used[a] = 1;
			used[b] = 1;
			int r = Calc(used, t+1);
			used[a] = 0;
			used[b] = 0;

			return r;
		}
		else if (count == 1) {
			int a = t;
			int b = 24 - t;

			used[a] = 1;
			int r = Calc(used, t + 1);
			used[a] = 0;

			if (a != b || t != 0) {
				used[b] = 1;
				int br = Calc(used, t + 1);
				chmax(r, br);
				used[b] = 0;
			}

			return r;
		}
		else if (count == 0) {
			return Calc(used, t + 1);
		}
		else {
			assert(false);
		}
	}
};

