int main(){
  ll N; cin >> N;
  vector<ll> cnt(13,0), D(N+1);
  D[0] = 0; cnt[0]++; //高橋くん
  REP(i,N){
    cin >> D[i+1];
    cnt[D[i+1]]++;
  }
  //0が2人以上いれば,必ずs=0
  if(cnt[0]>=2){
    cout << 0 << endl;
    return 0;
  }
  //D(>=1)が同じ人が3人以上いれば，必ずs=0
  FOR(i,1,13){
