int bitCount[13] = { 0, };

vector<int> make(int bit)
{
	if (bit == 12)
	{
		if (bitCount[bit] == 1)
			return vector<int> { 1 << 12 };
		else
			return vector<int> { 0 };
	}

	auto next = make(bit + 1);

	if (bitCount[bit] == 0)
		return next;

	if (bitCount[bit] == 1)
	{
		//둘 중에 하나 선택 가능
		vector<int> res;

		for (auto& ni : next)
		{
			res.push_back(ni | (1 << bit));
			res.push_back(ni | (1 << (24 - bit)));
		}

		return res;
	}
	else
	{
		// s != 0 이 되려면 항상 두 개를 서로 다른 위치에 배치해줘야 함
		for (auto& ni : next)
		{
			ni |= (1 << bit);
			ni |= (1 << (24 - bit));
		}

		return next;
	}
}

