	}

	for (int i = 1; i < 12; i++)
	{
		if (bitCount[i] >= 3)
		{
			printf("0\n");
			return 0;
		}
	}

	//0..12 까지 존재하는 숫자들 가지고 가능한 시간 배열 생성
	auto cases = make(1);

	int s = 0;

	for (auto& c : cases)
	{
		vector<int> p = { 0, };

		for (int i = 1; i < 24; i++)
		{
			if ((c & (1 << i)) != 0)
				p.push_back(i);
		}

		p.push_back(24);

		int g = 24;

		for (int i = 0; i < p.size() - 1; i++)
			g = min(g, p[i + 1] - p[i]);

		if (g == 24)
			continue;

		s = max(g, s);
	}

	printf("%d\n", s);

