void solve() {
  ll N;
  cin >> N;

  VL ds(N);

  map<ll, ll> cts;
  cts[0]++;

  rep(i, N) {
    ll d;
    cin >> d;

    ds[i] = d;
    cts[d]++;
  }

  if (cts[0] >= 2 || cts[12] >= 2) drop(0);
  rep1(i, 11) if (cts[i] >= 3) drop(0);

  ll res = 0;

  rep(bit, (1ll << 12) - 1) {
    VL ts(0);

    if (cts[0] > 0) ts.push_back(0);
    if (cts[12] > 0) ts.push_back(12);

    rep1(time, 11) {
      if (cts[time] == 0) continue;

      if (cts[time] == 2) {
        ts.push_back(time);
        ts.push_back(24-time);
        continue;
      }

      ll mask = 1ll << (time - 1);
      if ((bit & mask) == mask) {
        // 右側
        ts.push_back(time);
      } else {
        // 左側
        ts.push_back(24 - time);
      }
    }

    ll min_d = INF;

    rep(j, ts.size()) rep(i, j) {
      ll t_diff = abs(ts[i] - ts[j]);
      ll d = min(t_diff, 24- t_diff);
      chmin(min_d, d);
    }

    chmax(res, min_d);
  }

  cout << res << endl;
}

