bool isOk(vec<ll>& D, int diff){
    int lTop = 0;
    int rTop = 0;
    for(auto d: D){
        int lGap = d - lTop;
        int rGap = d - rTop;
        if(lGap < diff && rGap < diff){
            // impossible
            return false;
        }else if(lGap >= diff && rGap >= diff){
            // できるだけ後半をのこしておく。すすんでいる方をつぶす
            if(lTop >= rTop){
                // 左におく
                lTop = d;
            }else{
                rTop = d;
            }
        }else if(lGap >= diff){
            // 左におくしかない
            lTop = d;
        }else{
            // 右におくしかない
            rTop = d;
        }
        // 末尾が大丈夫か確認する
        int finalGap = 24 - lTop - rTop;
        if(finalGap < diff){
            // だめだった
            return false;
        }
    }
    return true;
}

