int dfs(map<int, int>::iterator it, vector<int> &times, map<int, int> &d) {
    int ret = 0;
    if (it == d.end()) {
        int mindiff = 25;
        int nt = times.size();
        for (int i = 0; i < nt; ++i) {
            for (int j = 0; j < nt; ++j) {
                if (i == j)
                    continue;
                int timemin = min(times[i], times[j]);
                int timemax = max(times[i], times[j]);
                chmin(mindiff, timemax - timemin);
                chmin(mindiff, 24 - timemax + timemin);
            }
        }
        return mindiff;
    }
    if (it->second == 1) {
        auto ntimes = times;
        ntimes.push_back(it->first);
        chmax(ret, dfs(next(it), ntimes, d));
        ntimes = times;
        ntimes.push_back(24 - it->first);
        chmax(ret, dfs(next(it), ntimes, d));
    }
    if (it->second == 2) {
        auto ntimes = times;
        ntimes.push_back(it->first);
        ntimes.push_back(24 - it->first);
        chmax(ret, dfs(next(it), ntimes, d));
    }
    return ret;
}

