bool f(int x, vector<int>& v) {
    vector<int> a, b;
    a.push_back(0);
    b.push_back(0);
    for (int i : v) {
        if (i - a.back() >= x) a.push_back(i);
        else b.push_back(i);
    }

    rep(i, a.size() - 1) {
        if (a[i + 1] - a[i] < x) return false;
    }

    rep(i, b.size() - 1) {
        if (b[i + 1] - b[i] < x) return false;
    }

    return x <= (12 - a.back()) + (12 - b.back());
}

