const int MAX_N=100+1;
int D[MAX_N];
int N;

int solve() {

  sort(D,D+N+1);
  REPE(x,24) {
    VI ng(48,0);
    auto ranges=[&](int t) -> VI {
      VI res;
      FOR(i,t-x,t+x) {
        if(i>=0&&i<SZ(ng)) res.push_back(i);
        if(i+24>=0&&i+24<SZ(ng)) res.push_back(i+24);
      }
      return res;
    };

    VI ts=ranges(D[0]);
    FORR(t,ts) ng[t]=1;
    FOR(i,1,N+1) {
//      dump(x,i,D[i]);
      if(!ng[D[i]]) {
        VI ts=ranges(D[i]);
        FORR(t,ts) ng[t]=1;
      } else if(!ng[24-D[i]]) {
        VI ts=ranges(D[i]);
        FORR(t,ts) ng[t]=1;
      } else {
        return x-1;
      }
    }
  }
  return 24;
}

