int solve(int *A){
    int s = 24;
    //0が連続する個数の最小を知りたい
    int row = 0;

    int i = 0;
    while(A[i] == 1) i++;
    for(; i < 24; i++){
        if(A[i] == 0) row++;
        else{
            if(row < s) s = row;
            while(A[i] == 1) i++;
            row = 1;
        }
    }
    if(row > 0 && row < s) s = row;
    return s+1;
}

