void solve(long long N, std::vector<long long> &D) {
	bool f = false;
	sort(D.begin(), D.end());
	int used[24] = { 1 };
	int ans = 24;
	for (int t : D) {
		f = !f;
		int i = f ? t : ((24 - t) % 24);
		if (++used[i] >= 2) {
			ans = 0;
		}
	}
	for (int i = 0; i < 24; ++i) {
		for (int j = i + 1; j < 24; ++j) {
			if (used[i] && used[j]) {
				ans = min(ans, j - i);
			}
		}
	}
	cout << ans << endl;
}

