int ans = 0;
vector<int> cnt(13, 0);

void func(int n, long long bit) {
  if (n == 13) {
    vector<int> tmp;
    for (int i = 0; i <= 24; i++) {
      if ((bit >> i) & 1) tmp.push_back(i);
    }
    int L = tmp.size();
    int diff = 24;
    for (int i = 1; i < L; i++) {
      diff = min(diff, tmp.at(i) - tmp.at(i-1));
    }
    ans = max(ans, diff);
    return;
  }
  if (cnt.at(n) == 0) {
    func(n+1, bit);
  }
  else if (cnt.at(n) == 1) {
    func(n+1, bit + (1LL << n));
    func(n+1, bit + (1LL << (24-n)));
  }
  else {
    func(n+1, bit + (1LL << n) + (1LL << (24-n)));
  }
}

