		return true;
	}
	return false;
}

//グラフ関連
struct Edge {//グラフ
	ll to, cap, rev;
	Edge(ll _to, ll _cap, ll _rev) {
		to = _to; cap = _cap; rev = _rev;
	}
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

void add_edge(Graph& G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
	G[from].push_back(Edge(to, cap, (ll)G[to].size()));
	if (revFlag)G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	ll n;
	cin>>n;
	Array d(n,0);
	REP(i,n) cin>>d[i];

	map<ll,ll> mp;
	mp[0]++;

	Array times;

	ll ans=INF;
	REP(i,n){
		mp[d[i]]++;
		if(mp[d[i]]==2){
			if(d[i]==0||d[i]==12){
				cout<<0<<endl;
				return 0;
			}
			chmin(ans,min(d[i]*2, 24-d[i]*2));
			times.push_back(d[i]);
			times.push_back(24-d[i]);
		}
		if(mp[d[i]]==3){
			cout<<0<<endl;
			return 0;
		}
	}

	for(auto i:mp){
		if(i.second==1){
			ll d1=INF;
			ll d2=INF;
			for(auto j:times){
				chmin(d1,min(abs(i.first-j),abs(24-(i.first-j))));
				chmin(d2,min(abs(24-i.first-j),abs(24-(24-i.first-j))));
			}
			if(d1>d2){
				times.push_back(i.first);
				chmin(ans, d1);
			}else{
				times.push_back(24-i.first);
				chmin(ans,d2);
			}
		}
	}

	cout<<ans<<endl;


	return 0;
}

