void dfs(V<ll>v,map<ll,ll>::iterator it){
    if(it==m.end()){
        ll s = INF;
        for(ll i=0;i<n+1;i++){
            for(ll j=i+1;j<n+1;j++){
                //cout<<v[i]<<" "<<v[j]<<Endl;
                ll x= mmax(v[i],v[j])-mmin(v[i],v[j]);
                if(x>12)x=24-12;
                chmin(s,x);
            }
        }
        chmax(ans,s);
        return;
    }
    if(it->fi==0||it->fi==12){
            for(ll k=0;k<it->se;k++){
                v.pb(it->fi);
            }
            dfs(v,++it);
        }
    else if(it->se==1){
        v.pb(it->fi);
        dfs(v,++it);
        --it;
        v.pop_back();
        v.pb(24-(it->fi));
        dfs(v,++it);
    }
    else{
        v.pb(it->fi);
        v.pb(24-(it->fi));
        dfs(v,++it);
    }
}
