		}
		if(D[12]==2){
			cout << 0 << endl;
		}
		if(d==0){
			cout << 0 << endl;
			return 0;
		}
	}

	vector<int> time,tp,pattern;
	time.push_back(12);//takahashi
	FOR(i,1,12){
		if(D[i]==2){
			time.push_back(12-i);
			time.push_back(12+i);
		}else if(D[i]==1){
			pattern.push_back(i);
		}
	}
	if(D[12]==1){
		time.push_back(0);
	}

	int ans = 0;
	FOR(i,0,(1<<(pattern.size()))){
		tp = time;
		FOR(j,0,pattern.size()){
			if(i&(1<<j)){
				tp.push_back(12-pattern[j]);
			}else{
				tp.push_back(12+pattern[j]);
			}
		}
		sort(tp.begin(),tp.end());
		int ansp = 100000;
		FOR(j,0,tp.size()-1){
			ansp = min(ansp,abs(tp[j]-tp[j+1]));
		}
		if(tp[0]==0){
			ansp = min(ansp,abs(24-tp[tp.size()-1]));
		}
		ansp = min(ansp,abs(tp[0]+24-tp[tp.size()-1]));
		ans = max(ans,ansp);
	}
	cout << ans << endl;
}
