void dfs(int num) {
	if (num == 13) {
		std::vector<int> ss = middle;

		if (ss.size() == 1)
			return;
		if (ss.size() == 2) {
			r = std::max(r, std::max(ss[0], ss[1]) - std::min(ss[0], ss[1]));
			return;
		}

		std::sort(ss.begin(), ss.end());
		int tmp = ss[0] + 24 - ss[ss.size() - 1];

		for (int i = 0; i < ss.size() - 1; i++)
			tmp = std::min(tmp, ss[i + 1] - ss[i]);
		r = std::max(r, tmp);
		return;
	}

	if (input[num] != 0) {
		if (num < maxA || (maxA == num && input[num] == 1)) {
			middle.push_back(num);
			dfs(num + 1);
			middle.pop_back();

			middle.push_back(24 - num);
			dfs(num + 1);
			middle.pop_back();
		}
		else if (maxA == num && input[num] > 1) {
			middle.push_back(num);
			middle.push_back(24 - num);
			dfs(num + 1);
			middle.pop_back();
			middle.pop_back();
		}
	}
	else if (input[num] == 0)
		dfs(num + 1);
}

