		 */
		int syurui=0;
		for(int i=0; i<=12; i++) {
			if(hrs[i]>0) {
				syurui++;
			}
		}
		for(int i=0; i<13; i++) {
			if(hrs[i]>2) {
				pl(0);
				System.exit(0);
			}
		}//同じ時差が3人以上いると、鳩ノ巣理論で0
		if(N==24 || N==23) {
			pl(0);
			System.exit(0);
		}

		times[0]=0;
		int[] tmp=new int[N+1];
		int p=1;
		for(int i=0; i<N; i++) {
			p*=2;
		}
		int max=0;
		int[] bucket=new int[25];
		for(int i=0; i<p; i++) {
			for(int j=0; j<25; j++) {
				bucket[j]=0;
			}
			int zent=i;
			for(int j=0; j<N; j++) {
				if(zent%2==0) {
					tmp[j+1]=times[j+1];
				}
				else if(zent%2==1) {
					tmp[j+1]=24-times[j+1];
				}
				zent/=2;
			}
			for(int j=0; j<N; j++) {
				bucket[tmp[j]]++;
			}
			int counter=0;
			for(int j=0; j<25; j++) {
				for(int k=0; k<bucket[j]; k++) {
					tmp[counter]=j;
					counter++;
				}
			}
			int dif=24;
			for(int j=1; j<=N; j++) {
				dif=Math.min(dif, tmp[j]-tmp[j-1]);
			}
			dif=Math.min(dif, 24-tmp[N]);
			max=Math.max(max, dif);
		}
		pl(max);
	}
	static class SC {
		private BufferedReader reader = null;
		private StringTokenizer tokenizer = null;
		public SC(InputStream in) {
			reader = new BufferedReader(new InputStreamReader(in));
		}
		public String next() {
			if (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new UncheckedIOException(e);
				}
			}
			return tokenizer.nextToken();
		}
		public int nextInt() {
			return Integer.parseInt(next());
		}
		public long nextLong() {
			return Long.parseLong(next());
		}
		public double nextDouble() {
			return Double.parseDouble(next());
		}
		public String nextLine() {
			try {
				return reader.readLine();
			} catch (IOException e) {
				throw new UncheckedIOException(e);
			}
		}
	}
