	int n; cin >> n;
	vi d(n); rep(i, n) cin >> d[i];

	if(n >= 12){ // ans <= 1
		cout << small_ans(n, d) << endl;
		return 0;
	}

	int ans = 0;
	rep(bit, 1 << n){
		vi v(1);
		rep(i, n) v.pb(bit >> i & 1 ? d[i] : (24 - d[i]) % 24);
		sort(all(v));
		int mn = 24;
		rep(i, v.size()){
			int diff = abs(v[i] - v[(i + 1) % v.size()]);
			mn = min(mn, min(diff, 24 - diff));
		}
		ans = max(ans, mn);
	}
	cout << ans << endl;
	return 0;
}

