  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll N;
  cin >> N;
  vll D(N+1);
  D.at(0) = 0;
  for(int i = 1; i <= N; i++){
    cin >> D.at(i);
  }
  sort(ALL(D));

  if(D.at(1) == 0){
    cout << 0 << endl;
    return 0;
  }

  ll ok = 0, ng = 24;

  ll ans = 0;
  while(ng - ok > 1){
    ll mid = (ok + ng) / 2;
    ll mini = 0, maxi = 24;
    vll A(N+1);
    A.at(0) = 0;
    bool flag = true;
    for(int i = 1; i <= N; i++){
      ll x = D.at(i), y = 24 - D.at(i);
      if(x - mini >= mid && maxi - y >= mid){
        if(x - mini > maxi - y){
          A.at(i) = y;
          maxi = y;
        }
        else{
          A.at(i) = x;
          mini = x;
        }
      }
      else if(x - mini >= mid){
        A.at(i) = x;
        mini = x;
      }
      else if(maxi - y >= mid){
        A.at(i) = y;
        maxi = y;
      }
      else{
        flag = false;
        break;
      }
    }
    if(flag){
      ok = mid;
      ll res = INF;
      sort(ALL(A));
      for(int i = 1; i <= N; i++){
        chmin(res, A.at(i) - A.at(i-1));
      }
      chmax(ans, res);
    }
    else ng = mid;
  }

  cout << ans << endl;
}

