vector<vl> t2;

void solve(){
    okay = true;
    rep(i, 13) cnt[i] = 1 * (i == 0);
    rep(i, n){
        in1(ds[i]);
        cnt[ds[i]]++;
        if (ds[i] == 0 || cnt[12] == 2 || cnt[ds[i]] >= 3)
            okay = false;
    }

    if (!okay){prl(0); return;}
    t1.pb(12); if (cnt[12] == 1) t1.pb(0);
    For(i, 1, 12){
        if (cnt[i] == 2) t1.pb(12 - i), t1.pb(12 + i);
        else if (cnt[i] == 1) t2.pb({12 - i, 12 + i});
    }

    ll k1 = t1.size(), k2 = t2.size(); vl now(n + 1);

