ll dfs(ll cur, ll bit){
  if(cur==0){
    if(m[cur]>=1)
      return 0;
    bit+=1;
    return dfs(cur+1,bit);
  }
  if(cur==13)
    return calc(bit);

  if(m[cur]==3)
    return 0;

  if(m[cur]==2){
    if(cur==12)
      return 0;
    return dfs(cur+1,bit+(1<<cur)+(1<<(24-cur)) );
  }

  if(m[cur]==1)
    return max(dfs(cur+1,bit+(1<<cur)), dfs(cur+1,bit+(1<<(24-cur) )));

  return dfs(cur+1,bit);
}

