void dfs(int i) {
  if (i == 13) {
    int last = 1, mind = INF;
    FORIN(j, 1, 25) {
      if (ans[j % 24]) {
        mind = min(mind, last);
        last = 1;
      } else {
        last++;
      }
    }
    fin = max(fin, mind);
  } else {
    if (D[i] == 1) {
      ans[i] = 1;
      dfs(i + 1);
      ans[i] = 0;
      ans[24 - i] = 1;
      dfs(i + 1);
      ans[24 - i] = 0;
