int N;
int num[16];

int calc(int bit)
{
	bool e[25]={0};
	e[0]=e[24]=1;

	for (int i = 1; i <= 12; ++i) {
		int c = bit % 2;
		bit /= 2;
		if (!num[i]) continue;
		if (num[i] == 2) {
			e[i] = e[24-i] = 1;
		} else {
			if (c == 0) {
				e[i] = 1;
			} else if (c == 1) {
				e[24-i] = 1;
			}
		}
	}

	int la = 0;
	int mi = 24;

	for (int i = 1; i <= 24; ++i) {
		if (e[i]) {
			mi = min(mi, i - la);
			la = i;
		}
	}

	return mi;
}

int main() {
	cin >> N;
	num[0] = 1;

	rep(i, N) {
		int x;
		cin >> x;

		if (x == 0 || num[x] == 2) {
			puts("0");
			return 0;
		}

		++num[x];
	}

	int ret = 0;
	rep(i, 1<<12) {
		ret = max(ret, calc(i));
	}

	cout << ret << endl;

	return 0;
}

