  for(ll i=0; i<=25; i++) {
    for(ll j=i+1; j<=25; j++) {
      if(d[i]==0 or d[j]==0) continue;
      //std::cout << i << " "<<j << std::endl;
      ans = min(ans, j-i);
    }
  }
  return ans;
}

void solve(long long N, std::vector<long long> D){
  vector<ll> d(25, 0);
  ll ans = 0;
  for(ll i=0; i<N; i++) {
    d[D[i]]++;
  }
  if(d[0]>0) {
    std::cout << 0 << std::endl;
    return ;
  }
  d[0]=1;
  for(ll i=0; i<=12; i++) {
    if(d[i]==2) {
      d[24-i]++;
      d[i]--;
    } else if(d[i]>=3) {
      std::cout << 0 << std::endl;
      return;
    }
  }
  ans = f(d);
  //std::cout << d << std::endl;
  for(ll i=1; i<=(1<<11); i++) {
    vector<ll> v(25, 0);
    if(d[12]==1) v[12]=1;
    if(d[0]==1) v[0] = 1;
    for(ll j=0; j<=11; j++) {
      if(i&(1<<j) and d[j]==1 and d[24-j]==0) {
	v[24-j]=1;
      }else {
	if(d[j]==1)
	  v[j]=1;
	if(d[24-j])
	  v[24-j]=1;
      }
    }
    ans = max(ans, f(v));
  }
  std::cout << ans << std::endl;
}

