bool solve(int t, const vector<int> &D) {
    vector<int> arr(24);
    auto can_place = [&] (int p) {
        rep(i, t) {
            if(arr[(p + i) % 24]) return false;
            if(arr[(p - i + 24) % 24]) return false;
        }
        return true;
    };
    for(int d : D) {
        if(can_place((12 + d) % 24)) {
            arr[(12 + d) % 24] = true;
        } else if(can_place((12 - d + 24) % 24)) {
            arr[(12 + d -+24) % 24] = true;
        } else {
            return false;
        }
    }
    return true;
}

