int calc(array<bool, 24>& arr, int i) {
    if(i == n) {
        int a = -24, min = 24;
        rep(k, 24) {
            if(arr[k]) {
                if(min > k - a) min = k - a;
                a = k;
            }
        }
        if(min > 24 - a) min = 24 - a;
        return min;
    } else {
        int x = 0, y = 0;
        if(!arr[d[i]]) {
            arr[d[i]] = true;
            x = calc(arr, i + 1);
            arr[d[i]] = false;
        }

        if(!arr[24-d[i]]) {
            arr[24-d[i]] = true;
            y = calc(arr, i + 1);
            arr[24-d[i]] = false;
        }

        if(x < y) x = y;
        return x;
    }
}

