ll cnt[13];

int main(void){
    int n,d;
    int ans=0,num=24;
    cin>>n;
    set<int>t;
    for(int i=0;i<n;i++){
        cin>>d;
        if(cnt[d]==0)t.insert(d);
        if(cnt[d]==1)t.insert(24-d);
        cnt[d]++;
    }
    int tsize=t.size();
    vector<int>tim(tsize),tim1;
    int index=0;
    for(auto itr=t.begin();itr!=t.end();++itr){
        tim[index++]=(*itr);
    }
    for(int i=0;i<(1<<tsize);i++){
        num=24;
        bool flag=false;
        tim1.clear();
        for(int j=0;j<tsize;j++){
            int digit=i>>j;
            if(cnt[tim[j]]>=3){
                num=0;
                flag=true;
                break;
            }
            if(tim[j]==0){
                tim1.push_back(tim[j]);
                continue;
            }
            if(digit&1)tim1.push_back(tim[j]);
            else tim1.push_back(24-tim[j]);
        }
        if(flag)continue;
        int si=tim1.size();
        for(int k=0;k<si;k++)num=min(num,tim1[k]);
        for(int j=0;j<si-1;j++){
            for(int k=j+1;k<si;k++){
                if(j==k)continue;
                int x=tim1[j]-tim1[k];
                if(x<0)x=-x;
                num=min(num,x);
            }
        }
        ans=max(ans,num);
    }
    cout<<ans<<endl;
    return 0;
}

