bool check(int diff) {
  for (int i=1;i<=n;i++) {
    if (d[i] < diff) {
      return false;
    }
  }
  for (int i=0;i<=n;i++) {
    for (int j=i+1;j<=n;j++) {
      if (abs(d[i] - d[j]) < diff && abs(24 - d[i] - d[j]) < diff) {
        return false;
      }
    }
  }
  return true;
}

void solve() {
