bool search_cities(ll n, const vector<ll>& D)
{
    vector<ll> cities(24,0);
    auto f = [n,&cities](ll p)
    {
        for(ll i=-n+1;i<n;i++)
        {
            if(cities[(p+i+24)%24]==0)
            {
                cities[(p+i+24)%24] = -1;
            }
        }
    };

    cities[0]=1;
    f(0);

    for(auto x : D)
    {
        if(cities[x]==0)
        {
            cities[x] = 1;
            f(x);
        }
        else if(cities[(24-x)%24]==0)
        {
            cities[(24-x)%24] = 1;
            f((24-x)%24);
        }
        else
        {
            return false;
        }
    }
    return true;
}

