int solve(int idx,int mask)
{
    if(idx == n)
    {
        int minNum = -1;
        for(int i = 0;i <= 24;i++)
        {
            for(int j = i+1;j <= 24;j++)
            {
                if(mask & (1<<i) && mask & (1 << j))
                {
                    if(minNum == -1)
                        minNum = 100;
                    minNum = min(minNum,abs(i-j));
                }
            }
        }
        return minNum;
    }
