vector<int> D(24, 0);

void f(int d)
{
  for (int j = d + 1; j <= d + 12; j++)
  {
    D[j % 24] = min(D[j % 24], j - d);
  }
  for (int j = d - 1; j >= d - 12; j--)
  {
    D[(j + 24) % 24] = min(D[(j + 24) % 24], d - j);
  }
}

int solve(int N)
{
  int d, ans = 24;
  for (int i = 0; i < N; i++)
  {
    cin >> d;
    if (D[d] == 0 && D[24 - d] == 0)
      return 0;
    if (D[d] >= D[24 - d])
    {
      D[d] = 0;
      f(d);
    }
    else
    {
      D[24 - d] = 0;
      f(24 - d);
    }
  }
  int c = 0;
  for (int i = 1; i <= 24; i++)
  {
    if (D[(i % 24)] == 0)
    {
      ans = min(c, ans);
      c = 0;
    }
    else
    {
      c++;
    }
  }
  return ans + 1;
}

