	ll N; cin >> N;
	ll d[51];
	int key[13];
	for (int i = 0; i < 13; ++i) {
		key[i] = 0;
	}
	key[0] = 1;
	REP(i, N) {
		cin >> d[i];
		if (d[i] == 0 || d[i] == 12) {
			key[d[i]]++;
		}
		else {
			if (d[i] < 12) {
				key[d[i]]++;
			}
			else {
				key[24 - d[i]]++;
			}
		}
	}
	if (N == 1) {
		cout << 0 << endl;
		return 0;
	}
	for (int i = 0; i <= 12; ++i) {
		if (i == 0||i==12) {
			if (key[i] >= 2) {
				cout << 0 << endl;
				return 0;
			}
		}
		else {
			if (key[i] >= 3) {
				cout << 0 << endl;
				return 0;
			}
		}
	}
	int ans = 0;
	vector<int>v;
	int visited[13];
	for (int i = 1; i < 12; ++i) {
		if (key[i] == 1) {
			v.push_back(i);
			visited[i] = 2;
		}
		else if (key[i] == 2)visited[i] = 0;
		else visited[i] = 1;
	}
	int m = v.size();
	for (ll i = 0; i < (1 << m); ++i) {
		vector<int>V;
		for (int j = 0; j < m; ++j) {
			if (i&(1 << j)) {
				V.push_back(v[j]);
			}
			else {
				V.push_back(24 - v[j]);
			}
		}
		for (int j = 1; j < 12; ++j) {
			if (visited[j] == 2)continue;
			if (visited[j] == 0) {
				V.push_back(j);
				V.push_back(24 - j);
			}
		}
		if (key[12])V.push_back(12);
		V.push_back(0);
		sort(V.begin(), V.end());
		int sum = 1e9;
		for (int j = 0; j < V.size() - 1; ++j) {
			sum = min(sum, V[j + 1] - V[j]);
		}
		sum = min(sum, 24 - V[V.size() - 1]);
		ans = max(ans, sum);
	}
	cout << ans << endl;
	return 0;
}

