int calc() {
	vector<int> x;
	for (int i = 0; i < 24; i++) if (used[i]) x.push_back(i);

	int score = 114514;
	for (int i = 0; i < (int)x.size(); i++) {
		//cout << x[i] << " ";
		if (i + 1 < (int)x.size()) score = min(score, x[i + 1] - x[i]);
	}
	//cout << endl;
	//cout << "score = " << score << endl;
	return score;
}

int dfs(int id) {
	if (id == n) { return calc(); }

	int a = d[id];
	int b = 24 - d[id];

	int ret = 1;
	int res;
	if (!used[a - 1] && !used[a] && !used[a + 1]) {
		used[a] = true;
		res = dfs(id + 1);
		ret = max(ret, res);
		used[a] = false;
	}
	if (!used[b - 1] && !used[b] && !used[b + 1]) {
		used[b] = true;
		res = dfs(id + 1);
		ret = max(ret, res);
		used[b] = false;
	}
	return ret;
}

