int main()
{
  init_main();

  int i, j, bi;
  int n;
  cin >> n;
  int d[50];
  for (i = 0; i < n; ++i)
    cin >> d[i];

  bool dp_next[1 << 24] = {}, dp[1 << 24] = {};
  dp[1] = true;
  for (i = 0; i < n; ++i)
  {
    for (bi = 0; bi < (1 << 24); ++bi)
    {
      if (!(bi & (1 << d[i])))
      {
        dp_next[bi | (1 << d[i])] |= dp[bi];
      }
      if (d[i] != 0 && d[i] != 12 && !(bi & (1 << (24 - d[i]))))
      {
        dp_next[bi | (1 << (24 - d[i]))] |= dp[bi];
      }
    }
    for (bi = 0; bi < (1 << 24); ++bi)
    {
      dp[bi] = dp_next[bi];
      dp_next[bi] = false;
    }
  }

  int Max = 0, Min;
  bitset<24> bs;

  for (bi = 0; bi < (1 << 24); ++bi)
  {
    if (!dp[bi])
      continue;
    Min = INF;
    bs = bitset<24>(bi);
    for (i = 0; i < 24; ++i)
      for (j = i + 1; j < 24; ++j)
      {
        if (bs[i] && bs[j])
          Min = min(Min, min(j - i, 24 - (j - i)));
      }
    Max = max(Max, Min);
  }
  cout << Max << "\n";
  return 0;
}

