int dfs(int cur,vector<int>& x){
  if(cur==12){
    vector<int> ans;
    rep(i,24){
      if(x[i] == 1)ans.push_back(i);
    }
    int d = ans[0] + 24 - ans[ans.size()-1];
    int ret = min(d,24-d);
    repp(i,1,ans.size()){
      d = ans[i] - ans[i-1];
      ret = min({ret,d,24-d});
    }
    return ret;
  }

  if(x[cur] !=-1) return dfs(cur+1,x);
  x[cur] = 1;
  x[24-cur] = 0;
  int ret = dfs(cur+1,x);
  x[cur] = 0;
  x[24-cur] = 1;
  ret = max(ret,dfs(cur+1,x));
  x[cur] = -1;
  x[24-cur] = -1;
  return ret;
}

