int B;

bool cmp(const int &a, const int &b) {
    if(a < B && b < B) return a < b;
    else if(a >= B && b >= B) return a < b;
    else return a >= B;
}

bool dist(int a, int b, int diff){
    if(a>b)swap(a,b);
    return (b - a >= diff) && (a + 24 - b >= diff);
}

