        if(m.count(mp(v[i], 24 - v[i]))) { // 使える
            if( dist(v[i], prev, diff) && dist(prev, a, diff) ) { // おける
                // if(b - a == 5)cout<<"if"<<endl;
                prev = v[i];
                if(m.count( mp(24 - v[i], v[i]) )) {
