                if(m.count( mp(v[i], 24 - v[i]) )) {
                    if(m[ mp(v[i], 24 - v[i]) ] > 1) m[ mp(v[i], 24 - v[i]) ]--;
                    else m.erase(m.find( mp(v[i], 24 - v[i]) ));
