                else m.erase(m.find( mp(v[i], 24 - v[i]) ));

                if(m.count(mp(24 - v[i], v[i]))) { // 次ある
                    continue;
                } else {

                    return false;
                }
            }
        }
    }
    return 1;
}

bool judge(int diff, vi d, int n) {
    // cout<<"ここjudge1"<<endl;
    map<pair<int, int>, int> m;
    vi v;
    rep(i, d.size()) {
        m[ mp(d[i], 24 - d[i]) ]++;
