namespace NyaGadget {}

namespace NyaGadget
{
	/***** Bit操作ライブラリ *****/

	struct NT_NyaaBit
	{
		/**
		@brief 1になっているビットの数を取得する
		@note flipをtrueにすると0になっているビットの数を返す。
		**/
		static long long Count(long long x, bool flip = false)
		{
			long long sum = 0;
			for (auto i = 0LL; i < Size(x); ++i) sum += Test(x, i, flip);
			return sum;
		}

		/**
		@brief bit列を整数に変換する
		**/
		static long long ToLL(std::string bit)
		{
			long long res = 0;
			long long maxSize = (long long)bit.size();
			for (auto i = 0LL; i < maxSize; ++i) if (bit[i] == '1') res += (1LL << (maxSize - i - 1));
			return res;
		}

		/**
		@brief 文字列に変換する
		**/
		static std::string ToString(long long x, bool flip = false)
		{
			std::string res;
			if (!flip) for (auto i = Size(x) - 1; -1 < i; --i) res += (char)('0' + Test(x, i));
			else       for (auto i = 0LL; i < Size(x); ++i)    res += (char)('0' + Test(x, i));
			return res;
		}

		/**
		@brief 文字列に変換する
		@note maxSize桁の文字列に変換する。
		**/
		static std::string ToString(long long maxSize, long long x, bool flip = false)
		{
			std::string res;
			for (auto i = 0LL; i < (maxSize - Size(x)); i++)   res += '0';
			if (!flip) for (auto i = Size(x) - 1; -1 < i; --i) res += (char)('0' + Test(x, i));
			else       for (auto i = 0LL; i < Size(x); ++i)    res += (char)('0' + Test(x, i));
			return res;
		}

		/**
		@brief 半開区間で1になっているビットの数を取得する
		@note
		値xの半開区間[b, e)でビットが1になっている数を返す。
		flipをtrueにすると0になっているビットの数を返す。
		**/
		static long long RangeCount(long long x, long long b, long long e, bool flip = false)
		{
			long long sum = 0;
			for (auto i = b; i < e; i++) sum += Test(x, i, flip);
			return sum;
		}

		/**
		@brief nビット左シフト
		**/
		static long long Shift(long long x, long long n)
		{
			return (x << n);
		}

		/**
		@brief 値xのビットサイズを取得する
		**/
		static long long Size(long long x)
		{
			long long size = 0;
			while ((long long)(1LL << size) <= x) size++;
			return size;
		}

		/**
		@brief 任意桁のビットを取得する
		@note flipがtrueなら反転したビット値を返す。
		**/
		static long long Test(long long x, long long i, bool flip = false)
		{
			if (flip) return ((x & Shift(1, i)) != 0) ? 0 : 1;
			else return ((x & Shift(1, i)) != 0) ? 1 : 0;
		}

		/**
		@brief 任意桁のビットを10進数に変換して返す
		@note 値xのi桁目ビットを10進数に変換して返す。
		**/
		static long long To10(long long x, long long i)
		{
			return Test(x, i) * (long long)pow(2, i);
		}

		/**
		@brief ビット組み合わせテーブル
		@note
		ビットサイズN桁でm個が1となるビット列の集合を昇順で返す。
		例えばN=4,m=2なら{0011, 0101, 0110, ... 1100}を返す。
		**/
		static void CombinationTable(long long N, long long m, std::vector<std::string>& res)
		{
			if (N <= 0 || m < 0) return;

			long long c = (1LL << m) - 1;
			while (c < 1LL << N)
			{
				res.push_back(ToString(N, c));
				long long x = c & -c, y = c + x;
				c = ((c) & ~y) / x >> 1LL | y;
			}
		}

		/**
		@brief ビット組み合わせテーブル
		@note
		ビットサイズN桁でm個が1となるビット列の集合を昇順で返す。
		例えばN=4,m=2なら{3(0011), 5(0101), 6(0110), ... 12(1100)}を返す。
		計算量は不明だが、素直な実装より高速に動作する。
		**/
		static std::vector<long long> CombinationTable(long long N, long long m)
		{
			std::vector<long long> res;
			if (N <= 0 || m < 0) return res;

			long long c = (1LL << m) - 1;
			while (c < 1LL << N)
			{
				res.push_back(c);
				long long x = c & -c, y = c + x;
				c = ((c) & ~y) / x >> 1LL | y;
			}
			return res;
		}

		static std::vector<long long> LtoB(long long x, bool flip)
		{
			std::vector<long long> res;
			auto size = NT_NyaaBit::Size(x);
			for (auto i = 0LL; i < size; ++i)
			{
				if (flip && NT_NyaaBit::Test(x, i) == 1) res.push_back(i);
				else if (!flip && NT_NyaaBit::Test(x, i) == 0) res.push_back(i);
			}
			return res;
		}
	};
}

namespace NyaGadget
{
	/*** ランレングス圧縮ライブラリ ***/

	template <class T> struct RunLengthEncodingResult
	{	// ランレングス圧縮の結果を格納する構造体
		long long begin = 0; // 区間開始位置
		long long end = 0;   // 区間終了位置
		std::vector<T> sub;  // 区間データ
	};

	template <> struct RunLengthEncodingResult<std::string>
	{	// ランレングス圧縮の結果を格納する構造体
		long long begin = 0; // 区間開始位置
		long long end = 0;   // 区間終了位置
		std::string sub;     // 区間データ
	};

	template <class T> struct DS_NyaaRLE
	{
		std::vector<RunLengthEncodingResult<T>> res;

		/**
		@brief 文字列のランレングス圧縮
		@param s 圧縮する文字列
		@param res 圧縮結果
		**/
		decltype(res)& Run(std::string& s)
		{
			res.push_back({ 0, 0, "" });
			for (long long i = 0; i < (long long)s.size(); i++)
			{
				if (i == (long long)s.size() - 1)
				{
					res.back().end = i + 1;
					res.back().sub = s.substr(res.back().begin, i + 1 - res.back().begin);
					return res;
				}
				if (s[i] != s[i + 1])
				{
					res.back().end = i + 1;
					res.back().sub = s.substr(res.back().begin, i + 1 - res.back().begin);
					res.push_back({ i + 1, 0, "" });
				}
			}
			return res;
		}

		/**
		@brief 配列のランレングス圧縮
		@param v 圧縮する配列
		@param res 圧縮結果
		**/
		decltype(res)& Run(std::vector<T>& v)
		{
			res.push_back({ 0, 0, std::vector<T>() });
			for (long long i = 0; i < (long long)v.size(); i++)
			{
				if (i == (long long)v.size() - 1)
				{
					res.back().end = i + 1;
					for (long long j = res.back().begin; j < i + 1; j++) res.back().sub.push_back(v[j]);
					return res;
				}
				if (!IsSame(v[i], v[i + 1]))
				{
					res.back().end = i + 1;
					for (long long j = res.back().begin; j < i + 1; j++) res.back().sub.push_back(v[j]);
					res.push_back({ i + 1, 0, std::vector<T>() });
				}
			}
			return res;
		}

		template <class T> bool IsSame(T& l, T& r)
		{	// lとrが同値かどうか調べる
			return l == r;
		}
	};
}


