using namespace std;

class SAT2 {
private:
  using Graph = std::vector<std::vector<int>>;
  Graph g, h;

public:
  SAT2(int n) : g(n * 2), h(n * 2) {}

  // var[i]=ii or var[j]=jj
  void add(int i, bool ii, int j, bool jj) {
    g[i * 2 + 1 - ii].push_back(j * 2 + jj);
    g[j * 2 + 1 - jj].push_back(i * 2 + ii);
    h[i * 2 + ii].push_back(j * 2 + 1 - jj);
    h[j * 2 + jj].push_back(i * 2 + 1 - ii);
  }

  std::vector<bool> build() {
    const int n = g.size();
    std::vector<int> cid(n, -1);
    std::vector<int> ord;
    int k = 0;
    std::function<void(const Graph &, int)> dfs = [&](const Graph &g, int u) {
      if (cid[u] >= 0) return;
      cid[u] = k;
      for (int v : g[u]) dfs(g, v);
      ord.push_back(u);
    };
    for (int i = 0; i < n; i++) dfs(g, i);
    std::fill(cid.begin(), cid.end(), -1);
    for (int i = n - 1; i >= 0; i--) {
      if (cid[ord[i]] == -1) {
        dfs(h, ord[i]);
        k++;
      }
    }
    std::vector<bool> var(n);
    for (int i = 0; i < var.size(); i++) {
      if (cid[i * 2] == cid[i * 2 + 1]) return {};
      var[i] = cid[i * 2] < cid[i * 2 + 1];
    }
    return var;
  }
};

int dist(int a, int b) {
  a %= 24;
  b %= 24;
  if (a > b) swap(a, b);
  return min(b - a, 24 - (b - a));
}

int main() {
  int n;
  cin >> n;

  vector<int> a(n + 1);
  for (int i = 0; i < n; i++) {
    cin >> a[i + 1];
  }

  for (int ans = 12; ans >= 0; ans--) {
    SAT2 sat(n + 1);
    for (int i = 0; i <= n; i++) {
      for (int j = i + 1; j <= n; j++) {
        if (dist(a[i], a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 1, j, 1);
        }
        if (dist(a[i], 24 - a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 1, j, 0);
        }
        if (dist(24 - a[i], 24 - a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 0, j, 1);
        }
        if (dist(24 - a[i], a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 0, j, 0);
        }
      }
    }
    auto ret = sat.build();
    if (!ret.empty()) {
      cout << ans << endl;
      return 0;
    }
  }
  cout << 0 << endl;
}

