    {
      for (int b = a + 1; b < time.size(); ++b)
      {
        int dif = std::abs(time[b] - time[a]);
        min = std::min(min, std::min(dif, 24 - dif));
      }
    }
    if (min > ans) ans = min;
    time.erase(std::next(time.begin(), sz), time.end());
  }
  printf("%d\n", ans);
