int N;
int D[13];

int rec(int idx, vector<int> v) {
  int res = 100000000;

  if (idx > 12) {
    sort(all(v));
    rep(i, v.size()) {
      int d = abs(v[(i + 1) % v.size()] - v[i]);
      res = min({res, d, 24 - d});
    }
  } else {
    if (D[idx] > 2) {
      return 0;
    } else if (D[idx] == 2) {
      v.eb(idx);
      v.eb((24 - idx) % 24);
      res = rec(idx + 1, v);
    } else if (D[idx] == 1) {
      vector<int> v1 = v, v2 = v;
      v1.eb(idx);
      v2.eb((24 - idx) % 24);
      res = max(rec(idx + 1, v1), rec(idx + 1, v2));
    } else {
      res = rec(idx + 1, v);
    }
  }

  return res;
}

