struct P {
    int time;
    int id;

    bool operator <(const P &another) {return time < another.time;}
};

bool is_ok(int s, const vector<P> &p) {
    int len = (int)p.size();
    {
        vector<bool> done(len / 2);
        done.at(p.at(0).id) = true;
        int before = p.at(0).time;
        for (int i = 1; i < len; i++) {
            if (done.at(p.at(i).id)) continue;

            if (p.at(i).time - before >= s) {
                done.at(p.at(i).id) = true;
                before = p.at(i).time;
            }
        }

        bool ok = true;
        for (int i = 0; i < len / 2; i++) {
            if (!done.at(i)) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    }

    {
        vector<bool> done(len / 2);
        done.at(len / 2 - 1) = true;
        int before = len / 2 - 1;
        for (int i = len / 2 - 2; i >= 0; i--) {
            if (done.at(p.at(i).id)) continue;

            if (before - p.at(i).time >= s) {
                done.at(p.at(i).id) = true;
                before = p.at(i).time;
            }
        }

        bool ok = true;
        for (int i = 0; i < len / 2; i++) {
            if (!done.at(i)) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    }

    return false;
}

