     UnionFind(int n):d(n,-1),cntWhite(n,0){};
     int deb(int x){
         return d[x];
     }
     int root(int x){
         if(d[x]<0)return x;
         return d[x]=root(d[x]);
     }
     int unite(int x,int y){
         x=root(x);y=root(y);
         if(d[x]>d[y])swap(x,y);
         d[x]+=d[y];
         cntWhite[x]+=cntWhite[y];
         d[y]=x;
         return true;
     }
     bool same(int x,int y){return root(x)==root(y);}
     int size(int x){return -d[root(x)];}
 };
