using namespace std;

struct SAT2 {
  vector<vector<int>> g;
  SAT2(int n) : g(n * 2, vector<int>(n * 2)) {};

  void add(int i, bool ii, int j, bool jj) {
    g[i * 2 + 1 - ii][j * 2 + jj] = true;
    g[j * 2 + 1 - jj][i * 2 + ii] = true;
  }

  bool can() {
    const int n = g.size();
    for (int k = 0; k < n; k++)
    for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      g[i][j] |= g[i][k] & g[k][j];
    for (int i = 0; i < n / 2; i++) {
      if (g[i * 2][i * 2 + 1] && g[i * 2 + 1][i * 2]) return false;
    }
    return true;
  }
};

int dist(int a, int b) {
  a %= 24;
  b %= 24;
  if (a > b) swap(a, b);
  return min(b - a, 24 - (b - a));
}

