    SAT2 sat(n + 1);
    for (int i = 0; i <= n; i++) {
      for (int j = i + 1; j <= n; j++) {
        if (dist(a[i], a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 1, j, 1);
        }
        if (dist(a[i], 24 - a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 1, j, 0);
        }
        if (dist(24 - a[i], 24 - a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 0, j, 0);
        }
        if (dist(24 - a[i], a[j]) < ans) {
          // not a[i] or not a[j]
          sat.add(i, 0, j, 1);
        }
      }
    }
    if (sat.can()) {
      cout << ans << endl;
      return 0;
    }
  }
  cout << 0 << endl;
}

