int dfs(int cur,vector<int>& x){
  if(cur==12){
    vector<int> ans;
    rep(i,24){
      if(x[i] == 1)ans.push_back(i);
    }
    int d = ans[0] + 24 - ans[ans.size()-1];
    int ret = min(d,24-d);
    repp(i,1,ans.size()){
      d = ans[i] - ans[i-1];
      ret = min({ret,d,24-d});
    }
    return ret;
  }

  if(x[cur] !=-1) return dfs(cur+1,x);
  x[cur] = 1;
  x[24-cur] = 0;
  int ret = dfs(cur+1,x);
  x[cur] = 0;
  x[24-cur] = 1;
  ret = max(ret,dfs(cur+1,x));
  return ret;
}

int solve(){
  int N;cin >> N;
  vector<int> v(N);
  vector<int> w(13);
  rep(i,N){
    cin >> v[i];
    ++w[v[i]];
  }
  //-1は未定
  vector<int> x(24,-1);
  if(w[0] > 0)return 0;
  x[0] = 1;
  if(w[12] > 1) return 0;
  if(w[12] == 1) x[12] = 1;
  else x[12] = 0;
  repp(i,1,12){
    if(w[i]>2) return 0;
    if(w[i] == 2){
      x[i] = 1;
      x[24-i] = 1;
    }
    if(w[i] == 0){
      x[i] = 0;
      x[24-i] = 0;
    }
  }
  return dfs(1,x);
}

