int count(vector<int> &vis)
{
  int mi = INT_INF;
  for (int i = 0; i < 24; i++)
  {
    for (int j = 0; j < 24; j++)
    {
      if (vis[i] && vis[j] && i != j)
      {
        int d1 = abs(i - j);
        int d2 = 24 - d1;
        int d = min(d1, d2);
        mi = min(mi, d);
      }
    }
  }
  return mi;
}

