    vector<int> times_after_1(n + 2);
    vector<int> times_after_2(n + 2);
    times_after_1[1] = 24;
    times_after_2[1] = 24;

    REP(i, n) {
        if (i % 2 == 0) {
            times_after_1[i + 2] = min(times[i], 24 - times[i]);
            times_after_2[i + 2] = max(times[i], 24 - times[i]);

