int mindiff(int bit){

    int result = INT_MAX;
    int tmp = 1;

    rep(i, 23){
        if(bit & (1<< i + 1)){
            result = min(result, tmp);
            tmp = 1;
        }else{
            tmp++;
        }
    }

    result = min(result, tmp);

    return result;
}


