vector<ll> tsort(Graph G)
{
    ll N = G.size();
    vector<ll> in(N);
    for (auto &&edges : G)
    {
        for (auto &&edge : edges)
        {
            in[edge]++;
        }
    }

    queue<int> que;

    for (int i = 0; i < N; i++)
    {
        if (in[i] == 0)
        {
            que.push(i);
        }
    }
    int cnt = 0;
    vector<ll> ans;
    while (!que.empty())
    {
        int v = que.front();
        que.pop();
        ans.push_back(v);
        for (auto &&next : G[v])
        {

            in[next]--;
            if (in[next] == 0)
            {
                que.push(next);
            }
        }
    }
    return ans;
}


void solve(long long N, std::vector<long long> D){
    map<ll,ll> cnt;
    for (int i = 0; i < N; i++)
    {
        cnt[D[i]]++;
    }
    cnt[0]++;
    if(cnt[0] >= 2 || cnt[12] >= 2){
        cout << 0 << endl;
        return;
    }
    for (int i = 1; i < 12; i++)
    {
