            return;
        }
    }


    vector<ll> st(N+1,-1);

    RSORT(D);
    st[0] = D[0];

    for (int i = 1; i < N; i++)
    {
        ll one = D[i];
        ll two = 24 - D[i];
        if(abs(st[i-1]-one)> abs(st[i-1]-two)){
