        cin >> N;
        D.resize(N);
        for (int i = 0; i < N; i++) cin >> D[i];
        D.push_back(0);
    }

    void solve() {
        vector<int> count(13, 0);
        for (int i = 0; i < D.size(); i++) {
            count[D[i]]++;
        }
        vector<int> X;
        for (int i = 0; i < 13; i++) {
            if (count[i] >= 3) {
                cout << 0 << endl;
                return;
            }
            if (count[i] >= 2 && (i == 0 || i == 12)) {
                cout << 0 << endl;
                return;
            }
        }
        if (count[1] >= 1) {
            cout << 1 << endl;
            return;
        }
        for (int i = 0; i < 13; i++) {
            for (int j = 0; j < min(count[i], 2); j++) {
                X.push_back(i);
            }
        }
        sort(whole(X));
        auto n = X.size();
        auto ans = 0;

        auto f = [&](int bit) {
            vector<int> d(n, 0);
            for (int i = 0; i < n; i++) {
                if (bit & (1 << i)) {
                    d[i] = X[i];
                } else {
                    d[i] = 24 - X[i];
                }
                if (d[i] < ans) return;
                if (i >= 1) {
                    int t = abs(d[i] - d[i - 1]);
                    if (min(t, 24 - t) < ans) return;
                }
            }
            sort(whole(d));
            int ret = 12;
            for (int i = 0; i < n; i++) {
                int j = (i + 1) % n;
                auto t = abs(d[i] - d[j]);
                ret = min(ret, min(t, 24 - t));
                if (ret < ans) return;
            }
            ans = max(ans, ret);
        };

        for (int bit = 0; bit < (1<<n); bit++) {
            f(bit);
        }
        cout << ans << endl;
    }
