int solve(ll N, vector<ll> D) {
  sort(ALL(D));
  vector<int> cnt(13);
  REP(i,N) cnt[D[i]]++;
  if (*max_element(ALL(cnt)) > 2) return 0;
  if (cnt[0] >= 1) return 0;
  if (cnt[12] >= 2) return 0;

  if (N >= 12) return 1;
  int res = 0;
  REP(bit,1<<N) {
    vector<int> d;
    REP(i,N) {
      if ((bit >> i) & 1) d.push_back(D[i]);
      else d.push_back(24 - D[i]);
    }
    d.push_back(0);
    sort(ALL(d));
    int mires = 1e9;
    REP(i,N) chmin(mires, d[i+1] - d[i]);
    chmax(res, mires);
  }
  return res;
}

