int dfs(int d, multiset<int> &st){
    if(d == 13){
        int mn = 100000000;
        vector<int> vec;

        for(auto it = st.begin(); it != st.end(); it++){
            vec.push_back(*it);
        }

        int sz = vec.size();
        for(int i = 0; i < sz; i++){
            for(int j = i + 1; j < sz; j++){
                mn = min(mn, min(vec[j] - vec[i], 24 - (vec[j] - vec[i])));
            }
        }

        return mn;
    }

    int ret = 0;

    if(mp[d] >= 3){
        ret = 0;
    }
    else if(mp[d] == 2){
        st.insert(d);
        st.insert(24 - d);
        ret = dfs(d + 1, st);
        auto it = st.find(d);
        st.erase(it);
        it = st.find(24 - d);
        st.erase(it);
    }
    else if(mp[d] == 1){
        st.insert(d);
        int c1 = dfs(d + 1, st);
        st.erase(d);
        st.insert(24 - d);
        int c2 = dfs(d + 1, st);
        st.erase(d);
        ret = max(c1, c2);
    }
    else if(mp[d] == 0){
        ret = dfs(d + 1, st);
    }

    return ret;
}

