    dfs( idx+1, bit|1ll<<(24-D[idx-1]) );
  }
  else
  {
    if( bit>>dm2&1 )
      dfs( idx+1, bit|1<<dm );
    else
      dfs( idx+1, bit|1<<dm2 );
