void dfs(int v) {
  if (v == n) {
    int gap = 26;
    int last = 0;
    for (int i = 1; i < 24; i++) {
      if (taken[i]) {
        gap = min(gap, i - last);
        last = i;
      }
    } 
    gap = min(gap, 24 - last);
    ans = max(ans, gap);
    return;
  }
  if (!taken[d[v]]) {
    taken[d[v]]++;
    dfs(v + 1);
    taken[d[v]]--;
  }
  int other = (24 - d[v]) % 24;
  if (other != d[v] && !taken[other]) {
    taken[other]++;
    dfs(v + 1);
    taken[other]--;
  }
}

