int Search(int n, int x, vector<int> &d) {
	if (n == 13) {
		int a = 0, b = 1, ans = 12;
		while (x > 0) {
			if (x & 1) {
				ans = min(ans, b - a);
				a = b;
			}
			x >>= 1;
			b++;
		}
		return min(ans, 24 - a);
	}
	if (d[n] == 0)
		return Search(n + 1, x, d);
	if (d[n] == 1)
		return max(Search(n + 1, x + (1 << (n - 1)), d), Search(n + 1, x + (1 << (23 - n)), d));
	return Search(n + 1, x + (1 << (n - 1)) + (1 << (23 - n)), d);
}

