bool cp(string s) {
    PRI(s)
    if (s.size() % 2 == 0) {
        int n = s.size() / 2;
        vector<char> c;
        REP(i, n) {
            c.push_back(s[i]);
        }
        FOR(i, n, s.size() - 1) {
            if (c[i - n] != s[i])return false;
        }

        return true;
    } else {
        int n = s.size() / 2;
        vector<char> c;
        REP(i, n)c.push_back(s[i]);
        FOR(i, n + 1, s.size() - 1)if (c[i - n + 1] != c[i])return false;
        return true;
    }
}

