            else if(i>>j&1)D[d[j+1]]++;
            else D[24-d[j+1]]++;
        }
        int now = 0, M = 12;
        for(int j:D)if(j>=2)M=0;
        for(int j=1; j<24; j++){
            if(D[j]){M=min(M,j-now);now=j;}
        }
        M=min(M,24-now);
        ans=max(ans,M);
    }
    cout<<ans<<endl;
    return 0;
}

