	lint extGCD(lint a, lint b, lint& x, lint& y) {
		if (b == 0) {
			x = 1;
			y = 0;
			return a;
		}
		lint d = extGCD(b, a % b, y, x);
		y -= a / b * x;
		return d;
	}

