using namespace std;
const int kMaxValue = 12;

int main() {
    int n; cin >> n;
    vector<int> v(n, 0);
    vector<int> f(kMaxValue + 1, 0);

    for (int i = 0; i < n; i += 1) {
        cin >> v[i];
        f[v[i]] += 1;

        if (f[v[i]] >= 3) {
            cout << "0\n";
            return 0;
        }
    }

    if (f[0] >= 1) {
        cout << "0\n";
        return 0;
    }

    if (f[12] >= 2) {
        cout << "0\n";
        return 0;
    }

    vector<int> state (2 * kMaxValue + 1, 0); 
    vector<int> others;
    state[0] = 1;

    for (int i = 1; i <= 12; i += 1) {
        if (f[i] == 2) {
            state[i] = 1;
            state[24 - i] = 1;
        } else if(f[i] == 1) {
            others.push_back(i);
        }
    }

    int k = others.size();
    int ans = 0;

    auto eval = [] (vector<int> state) {
        int ans = kMaxValue + 1;
        for (int i = 0; i <= 23; i += 1)
            for (int j = i + 1; j <= 23; j += 1)
                if (state[i] and state[j])
                    ans = min(ans, min(j - i, 24 - (j - i)));

        return ans;
    };

    for (int mask = 0; mask < (1 << k); mask += 1) {
        vector<int> temp_state = state;
        for (int i = 0; i < k; i += 1) {
            if ((1 << i) & mask) {
                temp_state[others[i]] = 1;
            } else {
                temp_state[24 - others[i]] = 1;
            }
        }

        ans = max(ans, eval(temp_state));
    }

    cout << ans << "\n";
}

