ll LLpow(ll x, ll n) {
	ll ret = 1;
	while (n > 0) {
		if (n & 1) {
			ret *= x;
		}
		x *= x;
		n >>= 1;
	}
	return ret;
}

int main() {
	ll N;
	cin >> N;
	vector<ll> D(N);
	rep(i, N) {
		cin >> D[i];
	}

	vll count(13, 0);
	rep(i, N) {
		count[D[i]]++;
	}

	if (count[0] > 0 || count[12] >= 2) {
		cout << 0 << endl;
		return 0;
	}

	vector<bool> selectBase(24, false);
	selectBase[0] = true;
	vvll selectTable(0, vll(0));
	ll numSelectNum = 0;

	if (count[12] == 1) {
		selectBase[12] = true;
	}

	reps(i, 1, 11) {
		if (count[i] >= 3) {
			cout << 0 << endl;
			return 0;
		}
		else if (count[i] == 2) {
			selectBase[i] = true;
			selectBase[24 - i] = true;
		}
		else if (count[i] == 1) {
			numSelectNum++;
			selectTable.push_back(vll(2));
			selectTable[numSelectNum - 1][0] = i;
			selectTable[numSelectNum - 1][1] = 24 - i;
		}
	}

	ll result = 0;
	ll numPattern = LLpow(2, numSelectNum);

	rep(p, numPattern) {
		vector<bool> select(24, false);
		rep(i, 24) {
			select[i] = selectBase[i];
		}

		ll pBit = p;
		ll tempRes = INF;
		rep(i, numSelectNum) {
			ll selectedHour = selectTable[i][(pBit % 2)];
			if (select[selectedHour] == true) {
				tempRes = 0;
				break;
			}
			else {
				select[selectedHour] = true;
			}
			pBit >>= 1;
		}

		if (tempRes > 0) {
			ll prevHour = 0;
			reps(i, 1, 24) {
				if (select[i] == true) {
					chmin(tempRes, i - prevHour);
					prevHour = i;
					//最後の選択から24時までの時差は、この後★で評価される
				}
			}
		}

		chmax(result, tempRes);
	}

	//★
	rep(i, N) {
		chmin(result, D[i]);
	}

	cout << result << endl;

	return 0;
}

