int calc_MIN(int b){ // 0 <=  b < 1<<24
  int MIN=12;
  int prev = -1;
  bool flag = false;
  rep(i, 25)  {
    if (i==0) continue;
    int mask = 1<<i;
    if (b & mask) {
      if (!flag) MIN = i;
      else MIN = min(MIN, i-prev);
      prev = i;
      flag = true;
    }
  }
  return MIN;
}

void create_vec(int idx, stack<int> st) {
  if (idx==14) {
    int d=0;
    while(!st.empty()) {
      int q = st.top();st.pop();
      d+=(1<<q);
    }
    d+=1<<24;
    V.push_back(d);
    return;
  }
  if (c[idx]==1) {
    st.push(idx);
    create_vec(idx+1, st);
    st.pop();
    if (idx > 0 && idx < 12) {
      st.push(24-idx);
      create_vec(idx+1, st);
    }
  } else if(c[idx]>1) { // 同じものに関しては最終的に0になり、候補外 
    st.push(idx);
    if (idx > 0) st.push(24-idx);
    create_vec(idx+1, st);
  }
  else create_vec(idx+1, st);
}

