using namespace std;
bool judge(set<int> st,int a){
    int past;
    for(auto itr = st.begin();itr!=st.end();itr++){
        if(itr==st.begin()) past = *itr;
        else{
            if((*itr-past)<a) return false;
            past = *itr;
        }
        //cout << past << endl;
    }
    if((24+*st.begin()-past)<a) return false;
    return true;
}
int main(){
    int n;
    cin >> n;
    int d[n];
    rep(i,n) cin >> d[i];
    sort(d,d+n);
    int tmpans = d[0];
    bool fl = true;
    while(true){
        set<int> st = {};
        fl = true;
        rep(i,n){
            if(i==0) st.insert(d[0]);
            else{
                auto itr = st.end();
                itr--;
                if((d[i]-*itr) < tmpans || (24+*st.begin()-d[i])<tmpans) st.insert(-d[i]);
                else if(*st.begin()+d[i] < tmpans || (24*d[i]-*itr) < tmpans) st.insert(d[i]);
                else{
                    if(*itr>abs(*st.begin())) st.insert(d[i]);
                    else st.insert(-d[i]);
                }
            }
            if(!judge(st,tmpans)){
                fl = false;
                break;
            }
        }
        if(fl) break;
        tmpans--;
    }
    cout << tmpans << endl;
}

