	if(n >= 24){
		cout << 0 << endl;
		return 0;
	}
	vector<int> ptime;
	sort(ALL(t));
	REP(i, n-1){
		if(t[i] == t[i+1]){
			if(i != n-2 && t[i] == t[i+2]){
				cout << 0 << endl;
				return 0;
			}
			else{
				ptime.pb(t[i]);
				t.erase(t.begin()+i);
