using ll = long long;

ll N;
ll D[60];
bool dp[60][30];
std::set<ll> S, nS;
ll ans = 0;
std::map<ll, ll> mp;

void dfs( int d, ll bit )
{
  if( d == 13 )
  {
    ll prv = 0;
    ll ret = 30;

    rep( d, 25 ) if( bit>>d&1 )
    {
      //printf( "%d ", d );
      ret = std::min( ret, d-prv );
      prv = d;
    }

    //puts("");

    chmax( ans, ret );

    return;
  }

  if( mp[d] >= 3 )
    return;

  if( mp[d] == 0 )
  {
    dfs( d+1, bit );

    return;
  }

  if( !d || d == 12 )
  {
    if( bit>>d&1 )
      return;

    dfs( d+1, bit|1ll<<d );

    return;
  }

  ll dm = std::min( d, 24-d );
  ll dm2 = std::max( d, 24-d );

  ll cnt = (bit>>dm&1)+(bit>>dm2&1);

  if( cnt > mp[d] )
    return;

  if( cnt == 2 )
    return;

  if( cnt == 0 && mp[d] == 2 )
  {
    dfs( d+1, bit|1ll<<d|1ll<<(24-d) );

    return;
  }

  if( cnt == 0 && mp[d] == 1 )
  {
    dfs( d+1, bit|1ll<<d );
    dfs( d+1, bit|1ll<<(24-d) );
  }

  if( cnt == 1 )
  {
    if( bit>>dm2&1 )
      dfs( d+1, bit|1<<dm );
    else
      dfs( d+1, bit|1<<dm2 );
  }

  return;
}

