int main(){
  ll N; cin >> N;
  vector<ll> cnt(13,0), D(N+1);
  D[0] = 0; cnt[0]++; //高橋くん
  REP(i,N){
    cin >> D[i+1];
    cnt[D[i+1]]++;
  }
  //0,12が2人以上いれば,必ずs=0
  if(cnt[0]>=2 || cnt[12]>=2){
    cout << 0 << endl;
    return 0;
  }
  //D(>=1)が同じ人が3人以上いれば，必ずs=0
  FOR(i,1,13){
    if(cnt[i]>=3){
      cout << 0 << endl;
      return 0;
    }
  }
  //同じDを取る人は2人以下
  //2人いる場合は別時刻としてよい
  ll U = (1<<12);
  ll ans = 0;
  vector<bool> use(24,false);
  use[0] = true;
  FOR(i,1,13){
    if(cnt[i]==2){
      use[i] = true;
      use[24-i] = true;
    }
