			for (int k = j+1; k < n; k++) {
				int diff = abs(d2[j] - d2[k]);
				diff = min(diff, 24 - diff);
				MIN = min(MIN, diff);
			}
		}

		for (int j = 0; j < n; j++) {
			int diff = d2[j];
			diff = min(diff, 24 - diff);
