using namespace std;

int val[13];

vector <int> last;
vector <int> at;


int main() {
	int n;
	scanf("%d", &n);
	val[0]++;
	for (int i = 0; i < n; ++i) {
		int x;
		scanf("%d", &x);
		val[x]++;
	}
	int ans = 0;
	last.push_back(0);

	for(int i = 0; i <= 12; i++){
		if(i == 0 || i == 12){
			if(val[i] == 0){
				for(int x: last){
					at.push_back(x);
				}
			}
			else if(val[i] == 1){
				for(int x: last){
					at.push_back(x|(1<<i));
				}
			}
			else{
				ans = -1;
				break;
			}
		}
		else{
			if(val[i] == 0){
				for(int x: last){
					at.push_back(x);
				}				
			}
			else if(val[i] == 1){
				for(int x: last){
					at.push_back(x|(1<<i));
					at.push_back(x|(1<<(24-i)));
				}			
			}
			else if(val[i] == 2){
				for(int x: last){
					at.push_back(x|(1<<i)|(1<<(24-i)));
				}						
			}
			else{
				ans = -1;
				break;
			}
		}
		last.clear();
		last = at;
		at.clear();
	}
	if (ans == -1) {
		printf("0\n");
		return 0;
	}
	for (int x : last) {
		vector <int> pos;
		for(int i = 0; i < 25; i++){
			if(x & (1 << i)){
				pos.push_back(i);
			}
		}
		int pn = pos.size();
		int an = 24;
		for (int j = 0; j < pn; j++) {
			int calc = pos[j+1]-pos[j];
			if(calc < 0) calc += 24;
			//printf("%x %d\n", x, calc);
			an = min(an, calc);
		}
		ans = max(ans, an);
	}
	printf("%d\n", ans);

}

