//(b以下の最大の数が欲しい場合は適宜帰着して使う)
int minimumMod(int a, int m, int k) {
	int res = (a - k) / m * m + k;
	if (a <= res - m)return res - m;
	if (a <= res)return res;
	return res + m;
}


