signed main() {
  int N;
  cin >> N;
  vector<int> D(N);
  map<int, int> mp;
  for (int i = 0; i < N; i++) {
    cin >> D[i];
    mp[D[i]]++;
  }

  if (N == 1) {
    cout << 0 << endl;
    return 0;
  }

  sort(ALL(D));
  UNIQUE(D)

  int ans = 0;
  for (int bit = 0; bit < Bit(D.size()); bit++) {
    vector<int> d;
    for (int i = 0; i < D.size(); i++) {
      if (mp[D[i]] > 1) {
        d.push_back(D[i]);
        d.push_back(24 - D[i]);
        continue;
      }
      if (Bitcheck(bit, i)) {
        d.push_back(D[i]);
      } else {
        d.push_back(24 - D[i]);
      }
    }
    d.push_back(0);

    int tmp = INF;
    for (int i = 0; i < d.size(); i++) {
      for (int j = i + 1; j < d.size(); j++) {
        chmin(tmp, abs(d[i] - d[j]));
      }
    }

    chmax(ans, tmp);
  }

  cout << ans << endl;
  return 0;
}

