ll binpow(ll a, ll ex, ll p) { //繰り返し二乗法
	ll result=1;
	while(ex>0) {
		if(ex&1) result=result*a%p;
		ex>>=1;
		a=a*a%p;
	}
	return result;
}


int N;
int D[13];
int res=0;

void input() {
	cin>>N;
}

void solve() {
	D[0]=2; D[12]=1;
	for(int i=0; i<N; i++) {
		int d; cin>>d;
		D[d]++;
		if(D[d]>2) {
			cout<<0<<endl;
			return;
		}
	}

	for(int bit=0; bit<(1<<24); bit++) {
		if(!(bit&1)) continue;
		if((D[12]==2) ^ ((bit>>12)&1)) continue;
		bool fault=false;
		for(int i=1; i<12; i++) {
			switch(D[i]) {
				case 0: {
					if((bit>>i)&1 || (bit>>(24-i))&1) fault=true;
					break;
				}
				case 1: {
					if(!( ((bit>>i)&1) ^ ((bit>>(24-i))&1) )) fault=true;
					break;
				}
				case 2: {
					if(!((bit>>i)&1) || !((bit>>(24-i))&1) ) fault=true;
					break;
				}
				default: {
					cout<<-1<<endl;
					return;
				}
			}
			if(fault) break;
		}
		if(fault) continue;

		int restmp=24;
		int tmp=0;
		for(int i=1; i<=24; i++) {
			tmp++;
			if((bit>>(i%24))&1) {
				chmin(restmp,tmp);
				tmp=0;
			}
		}
		chmax(res,restmp);
	}
	cout<<res%24<<endl;
}

int main() {
	int t=1;
	while(t) {
		input();
		solve();
		t--;
	}
}

