std::vector<int> scc(const std::vector<std::vector<int>> &g) {
  const int n = g.size();
  std::vector<int> post;
  std::vector<bool> vis(n);
  std::vector<std::vector<int>> rg(n);

  std::function<void(int)> dfs = [&](int u) {
    vis[u] = true;
    for (int v : g[u]) {
      if (!vis[v]) dfs(v);
      rg[v].push_back(u);
    }
    post.push_back(u);
  };
  for (int i = 0; i < n; i++) {
    if (!vis[i]) dfs(i);
  }

  std::reverse(post.begin(), post.end());

  int k = 0;
  std::vector<int> ret(n, -1);
  std::function<void(int)> dfs2 = [&](int u) {
    ret[u] = k;
    for (int v : rg[u]) if (ret[v] == -1) dfs2(v);
  };

  for (int u : post) {
    if (ret[u] == -1) {
      dfs2(u);
      k++;
    }
  }
  return ret;
}

// c=(i,ii,j,jj), x[i]==ii and x[j]==jj
std::vector<bool> sat2(int n, std::vector<std::tuple<int, int, int, int>> cs) {
  std::vector<std::vector<int>> g(n * 2);

  for (auto c : cs) {
    int i, ii, j, jj;
    std::tie(i, ii, j, jj) = c;
    // not a -> b = a or b
    g[i * 2 + 1 - ii].push_back(j * 2 + jj);
    g[j * 2 + 1 - jj].push_back(i * 2 + ii);
  }

  std::vector<int> sid = scc(g);
  std::vector<bool> ret(n);

  for (int i = 0; i < n; i++) {
    if (sid[i * 2] == sid[i * 2 + 1]) return {};
    ret[i] = sid[i * 2] < sid[i * 2 + 1];
  }

  return ret;
}

using namespace std;

int dist(int a, int b) {
  a %= 24;
  b %= 24;
  if (a > b) swap(a, b);
  return min(b - a, 24 - (b - a));
}

int main() {
  int n;
  cin >> n;

  vector<int> a(n + 1);
  for (int i = 0; i < n; i++) {
    cin >> a[i + 1];
  }

  for (int ans = 12; ans >= 0; ans--) {
    vector<tuple<int, int, int, int>> cs;
    for (int i = 0; i <= n; i++) {
      for (int j = i + 1; j <= n; j++) {
        if (dist(a[i], a[j]) < ans) {
          cs.emplace_back(i, 1, j, 1);
        }
        if (dist(a[i], 24 - a[j]) < ans) {
          cs.emplace_back(i, 1, j, 0);
        }
        if (dist(24 - a[i], 24 - a[j]) < ans) {
          cs.emplace_back(i, 0, j, 0);
        }
        if (dist(24 - a[i], a[j]) < ans) {
          cs.emplace_back(i, 0, j, 1);
        }
      }
    }
    if (!sat2(n + 1, cs).empty()) {
      cout << ans << endl;
      return 0;
    }
  }
  cout << 0 << endl;
}

