		REP(i, n) REP(j, 13) REP(k, 13) {
			if (!dp[i][j][k]) continue;
			if (d[i] - j >= minmax_dist && 24 - d[i] - k >= minmax_dist) dp[i + 1][d[i]][k] = true;
			if (d[i] - k >= minmax_dist && 24 - d[i] - j >= minmax_dist) dp[i + 1][j][d[i]] = true;
		}
		REP(j, 13) REP(k, 13) {
			if (dp[n][j][k]) {
				cout << minmax_dist << endl;
				return 0;
			}
		}
	}

	return 0;
}

