bool solve(int t, const vector<int> &D) {
    vector<int> arr(24);
    arr[12] = 1;
    auto can_place = [&] (int p) {
        rep(i, t) {
            if(arr[(p + i) % 24] > 0) return false;
            if(arr[(p - i + 24) % 24] > 0) return false;
        }
        return true;
    };
    function<bool(int)> dfs = [&] (int i) {
        if(i >= D.size()) return true;
        for(int d : {(12 + D[i]) % 24, (12 - D[i] + 24) % 24}) {
            if(can_place(d)) {
                arr[d]++;
                bool ok = dfs(i + 1);
                arr[d]--;
                if(ok) return ok;
            }
        }
        return false;
    };
    return dfs(0);
}

