void backtrack(int i) {
    if (i == n) {
        copy(foo, foo + n, p);
        sort(p, p + n);
        int s = 24;
        for (int i = 0, j = n - 1; i < n; j = i++) {
            s = min(s, min(abs(p[i] - p[j]), 24 - abs(p[i] - p[j])));
        }
        res = max(res, s);
    } else {
        for (int t = -1; t <= 1; t += 2) {
            foo[i] = d[i] * t;
            backtrack(i + 1);
            if (d[i] == 12) break;
        }
    }
}

