        vector<int> count(13, 0);
        for (int i = 0; i < D.size(); i++) {
            count[D[i]]++;
        }
        vector<int> X;
        for (int i = 0; i < 13; i++) {
            if (count[i] >= 3) {
                cout << 0 << endl;
                return;
            }
        }
        for (int i = 0; i < 13; i++) {
            for (int j = 0; j < min(count[i], 2); j++) {
                X.push_back(i);
            }
        }
        auto n = X.size();
        auto ans = 0;

        auto f = [&](int bit) {
            vector<int> d(n, 0);
            for (int i = 0; i < n; i++) {
                if (bit & (1 << i)) {
                    d[i] = X[i];
                } else {
