ll answer = 0;
ll n, ds[55], cnt[13];
vl t1;
vector<vl> t2;

void solve(){
    okay = true;
    rep(i, 13) cnt[i] = 1 * (i == 0);
    rep(i, n){
        in1(ds[i]);
        cnt[ds[i]]++;
        if (ds[i] == 0 || cnt[12] == 2 || cnt[ds[i]] >= 3)
            okay = false;
    }

    if (!okay){prl(0); return;}
    t1.pb(12); if (cnt[12] == 1) t1.pb(0);
    For(i, 1, 12){
        if (cnt[i] == 2) t1.pb(12 - i), t1.pb(12 + i);
        else if (cnt[i] == 1) t2.pb({12 - i, 12 + i});
    }

    ll k1 = t1.size(), k2 = t2.size(); vl now(n + 1);
    answer = 0;
    rep(i, k1) now[i] = t1[i];
    rep(i, 1LL << k2){
        ll c = 12;
        rep(j, k2) now[k1 + j] = t2[j][1LL << j & i];

        rep(i1, n) For(i2, i1 + 1, n + 1)
            chmin(c, min(24 - abs(now[i1] - now[i2]), abs(now[i1] - now[i2])));
        chmax(answer, c);
    }
    prl(answer);
}

