int n;

int dat[30];

int td[20]={};

int nt[25]={};

int dfs(int no){
	int res=100;
	if(no==n){
		rep(i,n){
			//printf(": %d\n",nt[i]);
			res = min(res,nt[i]);
			res = min(res,24-nt[i]);
			rep(j,i){
				res = min(res,abs(nt[j]-nt[i]));
			}
		}
		//printf("%d\n",res);
	}
	else{
		res=0;
		rep(i,2){
			int tt=dat[no];
			if(i)tt=24-tt;
			nt[no]=tt;
			res = max(res,dfs(no+1));
		}
	}
	return res;
}

