signed main() {
	INIT;
	VAR(int, n);
	VEC(int, d, n);
	std::vector<int> cnt(13, 0);
	REP(i, n) ++cnt[d[i]];
	int ans = -1;
	if (cnt[0] != 0) {
		ans = 0;
	}
	REP(i, 13) {
		if (cnt[i] > 2) ans = 0;
	}
	if (cnt[12] > 1) ans = 0;
	if (ans == 0) {
		OUT(0)BR;
		return 0;
	}
	std::vector<bool> base(24, false);
	base[0] = true;
	if (cnt[12] == 1) {
		base[12] = true;
	}
	REP(i, 13) {
		if (cnt[i] == 2) {
			base[i] = base[24 - i] = true;
		}
	}
	ans = 0;
	REP(i, (1 << 11)) {
		auto used(base);
		REP(j, 11) {
			if (cnt[j + 1] != 1) continue;
			if ((i >> j) & 1) {
				used[j + 1] = true;
			}
			else {
				used[24 - (j + 1)] = true;
			}
		}
		used.resize(48);
		REP(j, 24) used[j + 24] = used[j];
		int l = 0;
		int tans = INFINT;
		FOR(r, 1, 48) {
			if (used[r]) {
				int t = std::min(r - l, 24 - (r - l));
				CHMIN(tans, t);
				l = r;
			}
		}
		CHMAX(ans, tans);
	}
	OUT(ans)BR;

	return 0;
}

