int n;
int res;

void backtrack(int i) {
    if (i == n) {
        sort(p, p + n);
        int s = 24;
        for (int i = 0, j = n - 1; i < n; j = i++) {
            s = min(s, min(abs(p[i] - p[j]), 24 - abs(p[i] - p[j])));
        }
        res = max(res, s);
    } else {
        for (int t = -1; t <= 1; t += 1) {
            p[i] = d[i] * t;
            backtrack(i + 1);
        }
    }
}

