    if(time[0] >= 2 || time[12] >= 2){
        cout << 0 << endl;
        return 0;
    }
    REP(i, 13){
        if(time[i] >= 3){
            cout << 0 << endl;
            return 0;
        }
    }

    int ans = 0;
    REP(i, 1 << 11){
        vector<int> res;
        res.push_back(0);
        if(time[12] == 1) res.push_back(12);

        for(int j = 1; j <= 11; j++){
            if(time[j] == 0) continue;
            if(time[j] == 2){
                res.push_back(j);
                res.push_back(24 - j);
            } else {
                if(i >> (j - 1) & 1){
                    res.push_back(j);
                } else {
                    res.push_back(24 - j);
                }
            }
        }

        sort(all(res), greater<>());
        int tmp = inf;
        REP(i, res.size() - 1) chmin(tmp, res[i] - res[i + 1]);
        if(tmp != inf) chmax(ans, tmp);
    }
    cout << ans << endl;

    return 0;
}

