int scc(){
	fill(used, used+2*n+2, 0);
	vs.clear();
	for(int i=0; i<2*n+2; i++){
		if(!used[i]) dfs(i);
	}
	fill(used, used+2*n+2, 0);
	int k=0;
	for(int i=vs.size()-1; i>=0; i--){
		if(!used[vs[i]]) rdfs(vs[i], k++);
	}
	return k;
}
