void go (int in, vector < int > vec) {
    if (in == n) {
        int dif = inf;
        sort(all(vec));
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int q1 = vec[i];
                int q2 = vec[j];
                q2 -= q1;
                q1 = 0;
                dif = min(dif, min(q2, 24 - q2));
            }
