vector<vector<int>>memo(14,vector<int>(1<<13,-1));
int solve(bitset<12>v, int now, const vector<int>&nums) {
	if (memo[now][v.to_ulong()] != -1)return memo[now][v.to_ulong()];

	if (now == 13) {
		vector<int>times(24);
		for (int i = 0; i <= 12; ++i) {
			if (i == 0) {
				times[i] = true;
			}
			else if (i == 12) {
				if (nums[i])times[i] = true;
			}
			else {
				if (nums[i] == 2) {
					times[i] = true;
					times[24 - i] = true;
				}
				else if (nums[i] == 1) {
					if (v[i]) {
						times[i] = true;
					}
					else {
						times[24 - i] = true;
					}
				}
				else if (nums[i] >= 3)assert(false);
			}
		}
		int ans = 24;
		for (int i = 0; i < 24; ++i) {
			for (int j = i+1; j < 24; ++j) {
				if (times[i] && times[j]) {
					ans = min(ans, min(abs(i - j), 24 - abs(i - j)));
				}
			}
		}
		return memo[now][v.to_ulong()] = ans;
	}
	else if (now == 12) {
		if (nums[now] > 1) {
			return memo[now][v.to_ulong()] = 1;
		}
		else {
			return memo[now][v.to_ulong()] = solve(v, now + 1, nums);
		}
	}
	else {
		int ans = 0;
		if (nums[now] == 1) {
			v[now] = 0;
			ans = max(ans, solve(v, now + 1, nums));
			v[now] = 1;
			ans = max(ans, solve(v, now + 1, nums));
			v[now] = 0;
		}
		else if (nums[now] > 2) {
			return memo[now][v.to_ulong()] = 0;
		}
		else {
			ans = solve(v, now + 1, nums);
		}
		return memo[now][v.to_ulong()] = ans;
	}

}
