    (0 until (1 shl n)).asSequence().map { bit ->
        b.clear(1, 24)
        for (i in a.indices) {
            val j = if (bit.bit(i)) 24 - a[i] else a[i]
            if (b[j])
                return@map 0
            b[j] = true
        }

