fun solve() {
    val N = rd.readInt()
    val D = rd.readIntArray()

    if (N==1) {
        println(min(D[0], 24-D[0]))
        return
    }

    val A = Array(N) {IntPair(0,0)}
    for (i in 0 until N) {
        A[i] = IntPair(D[i], 24-D[i])
    }

    val B = IntArray(N-1){0}
    for (i in 0 until N-1) {
        B[i] = max(B[i], abs(A[i+1].first - A[i].first))
        B[i] = max(B[i], abs(A[i+1].first - A[i].second))
        B[i] = max(B[i], abs(A[i+1].second - A[i].first))
        B[i] = max(B[i], abs(A[i+1].second - A[i].second))
    }

    val ans = B.min()!!
    println(ans)
}


