fun bitFS(D: IntArray): Int {
    val N = D.size

    var res = 0
    for (p in 0 until (0b01 shl N)) {
        var ptn = p

        val A = IntArray(24){0}

        for (i in 0 until N) {
            if ((ptn and 0b01) == 1) {
                A[24-D[i]] += 1
            } else {
                A[D[i]] += 1
            }
            ptn = ptn shr 1
        }

        if (A.none { it > 1 }) {
            val dist = A.joinToString("")
                    .split('1').map{it.length}.min()!! + 1
            res = max(res, dist)
        }
    }

    return res
}

