fun solve() {
    val n = nextLong() + 1
    val d = longAry(n)
    d[0] = 0L
    for (i in 1 until n) d[i] = nextLong()
    val truetime = arrayOf(0L, 1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L, 11L, 12L)
    val falsetime = arrayOf(24L, 23L, 22L, 21L, 20L, 19L, 18L, 17L, 16L, 15L, 14L, 13L, 12L)

    var ans = -INF
    for (bit in 0 until (1 shl 13)) {
        val flag = boolAry(13)
        for (i in 0 until 13) {
            if(((bit shr i) and 1) == 1) flag[i] = true
        }

        var min = INF
        for (i in 0 until n - 1) {
            for (j in i + 1 until n) {
                val time1 = if(flag[d[i]]) truetime[d[i]] else falsetime[d[i]]
                val time2 = if(flag[d[j]]) truetime[d[j]] else falsetime[d[j]]
                var gap = abs(time1 - time2)
                if(d[i] == d[j]) gap = abs(truetime[d[i]] - falsetime[d[j]])
