/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] d = in.nextIntArray(n);
            Arrays.sort(d);
            for (int i = 0; i < n; i++) {
                if (i % 2 == 1) continue;

                d[i] = 24 - d[i];
            }
            Arrays.sort(d);
            int min = Math.min(d[0], 24 - d[n - 1]);
            for (int i = 0; i < n - 1; i++) {
                min = Math.min(min, d[i + 1] - d[i]);
            }

            out.println(min);
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public int[] nextIntArray(int n) {
            int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt();
            }
            return res;
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.util.*

fun Int.bit(i: Int) = 1 shl i and this > 0

fun main(A: Array<String>) {
    val s = Scanner(System.`in`)
    val n = s.nextInt()
    if (n > 24) {
        println(0)
        return
    }
    val a = IntArray(n) { Integer.parseInt(s.next()) }
    val b = BitSet(25)
    b.set(0)
    b.set(24)

    var r = 0
    outer@ for (f in 0..(1 shl n)) {
        b.clear(1, 24)
        for (i in 0 until n) {
            val j = if (1 shl i and f > 0) 24 - a[i] else a[i]
            if (b[j])
                continue@outer
            b.set(j)
        }
        val v = b.stream().skip(1)
                .map { o: Int -> o - b.previousSetBit(o - 1) }
                .min().asInt
        r = Math.max(r, v)
    }
    println(r)
}

