			for(int j = i+1; j<n; j++)
			{
				max = Math.max(max, dif(a[i],b[j]));
				max = Math.max(max, dif(b[i],a[j]));
				max = Math.max(max, dif(a[i],a[j]));
				max = Math.max(max, dif(b[i],b[j]));
			}
		}
		System.out.println(max);
	}

}

