	private static void solve() {
		int n = nei();
		int[] ds = nis(n);
		if (n >= 24)
			kil(0);
		if (n <= 11) {
			// brute 1
			int max = 1 << n;
			int[] bs = new int[n];
			int ans = 0;
			for (int i = 0; i < max; i++) {
				int minmax = 24;
				for (int j = 0; j < n; j++) {
					bs[j] = (i & (1 << j)) != 0 ? ds[j] : 24 - ds[j];
					minmax = min(minmax, min(bs[j], 24 - bs[j]));
				}
				for (int j = 1; j < n; j++) {
					for (int k = 0; k < j; k++) {
						int d = abs(bs[k] - bs[j]);
						minmax = min(minmax, min(d, 24 - d));
					}
				}
				if (minmax > ans)
					ans = minmax;
			}
			kil(ans);
		} else {
			// brute 2; can ans be 1?
			int max = 1 << n;
			boolean[] po = new boolean[25];
			L: for (int i = 0; i < max; i++) {
				for (int j = 0; j < 24; j++) {
					po[j] = false;
				}
				po[0] = true;
				for (int j = 0; j < n; j++) {
					int d = (i & (1 << j)) != 0 ? ds[j] : (24 - ds[j]) % 24;
					if (po[d])
						continue L;
					po[d] = true;
				}
				kil(1);
			}
			kil(0);
		}
		throw new RuntimeException();
