import static java.lang.System.in;

public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] D = new int[n];
        for(int i=0;i<n;i++) D[i]=sc.nextInt();
        int ans = help(D);
        System.out.println(ans);

    }
    static int help(int[] D){
        Arrays.sort(D);
        if(D[0]==0) return 0;
        int[] rec = new int[13];
        for(int i=0;i<D.length;i++){
            int cur = D[i];
            rec[cur]++;
            if(rec[cur]>2) return 0;
        }
        if(rec[12]>1) return 0;
        ArrayList<Integer> done = new ArrayList<>(), undone = new ArrayList<>();
        for(int i=1;i<12;i++){
            if(rec[i]==0) continue;
            if(rec[i]==2){
                done.add(i);
                done.add(24-i);
            }
            else undone.add(i);
        }
        if(rec[12]==1) done.add(12);
        if(undone.size()==0) return minGap(done);
        int len = undone.size();
        int ans = 0;
        for(int state=0;state<(1<<len);state++){
            for(int i=0;i<len;i++){
                if((state&(1<<i))==0) done.add(undone.get(i));
                else done.add(24-undone.get(i));
            }
            ans = Math.max(ans,minGap(done));
            for(int i=0;i<len;i++) done.remove(done.size()-1);
        }
        return ans;
    }
    static int minGap(ArrayList<Integer> time){
        int ans = 50;
        for(int w:time) ans = Math.min(ans,Math.min(w,24-w));
        for(int i=0;i<time.size();i++){
            for(int j=i+1;j<time.size();j++){
                int cur = Math.abs(time.get(i)-time.get(j));
                ans = Math.min(ans,Math.min(cur,24-cur));
            }
        }
        return ans;
    }
}

import java.util.*;

public class Main {
    public void main(Scanner sc) {
        int n = sc.nextInt();
        int d[] = new int[13];
        for (int i = 0; i < n; i++) {
            d[sc.nextInt()]++;
        }

        if (d[0] >= 1 || d[12] >= 2 || Arrays.stream(d).anyMatch(cnt -> cnt >= 3)) {
            System.out.println(0);
            return;
        }

        int len = 0;
        int one[] = new int[12];
        boolean time[] = new boolean[24];
        for (int i = 0; i <= 12; i++) {
            if (d[i] == 2) {
                time[d[i]] = true;
                time[(24 - d[i]) % 24] = true;
            } else if (d[i] == 1) {
                one[len++] = i;
            }
        }
        time[0] = true;

        int ans = 0;
        for (int i = 0; i < (1 << len); i++) {
            boolean tmp[] = time.clone();
            for (int j = 0; j < len; j++) {
                if ((i >> j) % 2 == 0) {
                    tmp[one[j]] = true;
                } else {
                    tmp[24 - one[j]] = true;
                }
            }
            ans = Math.max(ans, calc(tmp));
        }

        System.out.println(ans);
    }

    private int calc(boolean time[]) {
        int prv = 0;
        int ans = 25;
        for (int i = 1; i < 24; i++) {
            if (time[i]) {
                ans = Math.min(ans, i - prv);
                prv = i;
            }
        }
        ans = Math.min(ans, prv);

        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        new Main().main(sc);
        sc.close();
    }
}

