        public void solve(int testNumber, LightScanner in, LightWriter out) {
            Debug.autoEnable();
            int n = in.ints();
            int[] w = new int[13];
            for (int i = 0; i < n; i++) {
                if (++w[in.ints()] > 2) {
                    out.ans(0).ln();
