            List<Integer> times = new ArrayList<>();
            int ans = 0;
            for (int i = 0; i < 0b10000_0000_0000; i++) {
                times.clear();
                if (w[12] == 1) {
                    times.add(12);
                }
                for (int j = 1; j < 12; j++) {
                    if (w[j] == 0) {
                    } else if (w[j] == 1) {
                        if ((i & (1 << (j - 1))) == 0) {
                            times.add(j);
                        } else {
                            times.add(24 - j);
                        }
                    } else {
                        times.add(j);
                        times.add(24 - j);
                    }
                }
                int s = 24;
                for (int j = 0; j < times.size(); j++) {
                    for (int k = 0; k < j; k++) {
                        int d = (times.get(j) - times.get(k) + 24) % 24;
                        d = Math.min(d, 24 - d);
