                time[(24 - d[i]) % 24] = true;
            } else if (d[i] == 1) {
                one[len++] = i;
            }
        }
        time[0] = true;

        int ans = 0;
        for (int i = 0; i < (1 << len); i++) {
            boolean tmp[] = time.clone();
            for (int j = 0; j < len; j++) {
                if ((i >> j) % 2 == 0) {
                    tmp[one[j]] = true;
