public void solve() {
	int num = ni();
	int d[] = ni(num);
	int cnt[] = new int[13];
	cnt[0] ++;
	for(int i = 0; i < num; i ++) {
		cnt[d[i]] ++;
	}
	if(max(cnt) >= 3 || cnt[0] >= 2 || cnt[12] >= 2) exit(0);
	long max = 0;
	int maxBit = (int)bitFlag(11);
	for(int bit = 0; bit < maxBit; bit ++) {
		boolean b[] = new boolean[25];
		b[0] = true;
		b[24] = true;
		if(cnt[12] == 1) b[12] = true;
		for(int i = 0; i < 11; i ++) {
			if(cnt[i + 1] >= 2) {
				b[i + 1] = true;
				b[24 - i - 1] = true;
			}else if(cnt[i + 1] == 1) {
				b[i + 1] = isFlagged(bit, i);
				b[24 - i - 1] = !isFlagged(bit, i);
			}
		}
		long tmp = INF;
		int prv = 0;
		for(int i = 1; i < 25; i ++) {
			if(b[i]) {
				tmp = min(tmp, i - prv);
				prv = i;
			}
		}
		max = max(max, tmp);
	}
	prtln(max);
}


