	static int dfs(int i) {
		int max = 0;
		if(i==n) {
			max = 24;
			for(int j=0;j<25;j++) {
				for(int k=j+1;k<25;k++) {
					if(exist[j] && exist[k]) {
						int dif = Math.abs(j-k);
						max = min(max, min(dif, 24-dif));
					}
				}
			}
			return max;
		}
		if(exist[d[i]] && exist[24-d[i]]) {
			return 0;
		}
		if(exist[d[i]]) {
			exist[24-d[i]]=true;
			max = dfs(i+1);
		}
		else if(exist[24-d[i]]){
			exist[d[i]]=true;
			max = dfs(i+1);
		}
		else {
			exist[d[i]]=true;
			max = max(max, dfs(i+1));
			exist[d[i]]=false;
			exist[24-d[i]]=true;
			max = max(max, dfs(i+1));
		}
		return max;
