			for(int j=0; j<25; j++) {
				for(int k=0; k<bucket[j]; k++) {
					tmp[counter]=j;
					counter++;
				}
			}
			int dif=24;
			for(int j=1; j<=N; j++) {
				dif=Math.min(dif, tmp[j]-tmp[j-1]);
			}
			dif=Math.min(dif, 24-tmp[N]);
			max=Math.max(max, dif);
		}
		pl(max);
	}
