        int N = in.nextInt();
        int[] numD = new int[13];
        numD[0]++;
        for(int i = 0; i < N; i++) numD[in.nextInt()]++;

        ArrayList<Integer> T = new ArrayList<>();
        boolean isRight = true;
        for(int i = 0; i <= 12; i++){
            if(numD[i] == 0) continue;
            if(i == 0 || i == 12){
                if(numD[i] >= 2){
                    out.println("0");
                    return;
                }else{
                    T.add(i);
                }
            }else{
                if(numD[i] >= 3){
                    out.println("0");
                    return;
                }else if(numD[i] == 2){
                    T.add(i);
                    T.add(24-i);
                }else{
                    if(isRight) T.add(i);
                    else T.add(24-i);
                    isRight = !isRight;
                }
            }
        }

        int min = Integer.MAX_VALUE;
        for(int i = 0; i < T.size(); i++){
            for(int j = i + 1; j < T.size(); j++){
                min = Math.min(min, Math.abs(T.get(i) - T.get(j)));
            }
        }
        out.println(min);
    }

