						max = min(max, min(dif, 24-dif));
					}
				}
			}
			return max;
		}
		int plus = d[i]; plus %= 24;
		int minus = 24 - d[i]; if(minus < 0)minus += 24;
		if(exist[plus] && exist[minus]) {
			return 0;
		}
		else if(exist[plus]) {
			exist[minus]=true;
			max = dfs(i+1);
			exist[minus]=false;
		}
		else if(exist[minus]){
			exist[plus]=true;
			max = dfs(i+1);
			exist[plus]=false;
		}
		else {
			exist[plus]=true;
			max = max(max, dfs(i+1));
			exist[plus]=false;
			exist[minus]=true;
			max = max(max, dfs(i+1));
			exist[minus]=false;
		}
