				boolean diff = Math.min(d[i] + d[j], 24 - d[i] - d[j]) >= k;
				if (!same && !diff) {
					return false;
				}
				if (same && diff) {

				}else if(same){
					m[i][j] = m[j][i] = 1;
				}else{
					m[i][j] = m[j][i] = -1;
				}
			}
		}
//		System.out.println(Arrays.deepToString(m));
		int[] sgn = new int[n];
