			if (v==u || m[v][u] == 0) continue;
			int sgn2 = sgn[v] * m[v][u];
			if (sgn[u] != 0) {
				if (sgn[u] != sgn2) {
					//fail
					throw new RuntimeException();
				}
			}else{
				sgn[u] = sgn2;
				dfs(u,n,m,sgn);
			}
		}
	}


