	static int dfs(int i) {
		int max = 0;
		if(i==n) {
			max = 12;
			for(int j=0;j<24;j++) {
				for(int k=j+1;k<24;k++) {
					if(exist[j] && exist[k]) {
						int dif = Math.abs(j-k);
						max = min(max, min(dif, 24-dif));
					}
				}
			}
			return max;
		}
		int plus = takaT + d[i]; plus %= 24;
		int minus = takaT - d[i]; if(minus < 0)minus += 24;
		if(exist[plus] && exist[minus]) {
			return 0;
		}
		else if(exist[plus]) {
			exist[minus]=true;
			max = dfs(i+1);
		}
		else if(exist[minus]){
			exist[plus]=true;
			max = dfs(i+1);
		}
		else {
			exist[plus]=true;
			max = max(max, dfs(i+1));
			exist[plus]=false;
			exist[minus]=true;
			max = max(max, dfs(i+1));
		}
