	public void run() {

		try {
			//String S = sc.next().trim();
			int N = sc.nextInt();
			boolean[] time = new boolean[24];
			HashMap<Integer, Integer> hm = new HashMap<>();
			for (int i = 0; i < N; i++) {
				int d = sc.nextInt();
				if (N == 1) {
					out.println(d);
					return;
				}
				if (hm.containsKey(d)) {
					int count = hm.get(d) + 1;
					hm.put(d, count);
				} else {
					hm.put(d, 1);
				}
			}

			ArrayList<Integer> one = new ArrayList<Integer>();
			for (Entry<Integer, Integer> e : hm.entrySet()) {
				if (e.getKey() == 0 || e.getKey() == 12) {
					time[e.getKey()] = true;
					if (e.getValue() >= 2) {
						out.println(0);
						return;
					}
				} else {
					if (e.getValue() >= 3) {
						out.println(0);
						return;
					} else if (e.getValue() >= 2) {
						time[e.getKey()] = true;
						time[24 - e.getKey()] = true;
					} else {
						one.add(e.getKey());
					}
				}
			}

			int ans = 0;
			for (int bit = 0; bit < (1 << one.size()); bit++) {
				//out.println("bit:" + Integer.toBinaryString(bit));
				boolean[] times = time.clone();
				for (int j = 0; j < one.size(); j++) {
					if ((1 & bit >> j) == 1) {
						//out.println(j + " " + one.get(j));
						times[one.get(j)] = true;
					} else {
						times[24 - one.get(j)] = true;
					}
				}
				//out.println("time :" + Arrays.toString(time));
				//out.println("times:" + Arrays.toString(times));

				int min = Integer.MAX_VALUE;
				out: for (int i = 0; i < 23; i++) {
					if (times[i]) {
						for (int j = i + 1; j < 24; j++) {
							if (times[j]) {
								int w = Math.min(j - i, 24 - j + i);
								min = Math.min(min, w);
							}
						}
					}
				}
				ans = Math.max(ans, min);

			}

			out.println(ans);

		} catch (ArithmeticException ae) {
			//ae.printStackTrace();
			throw new RuntimeException();
		} catch (Exception e) {
			e.printStackTrace();
			throw new RuntimeException();
		} finally {
			out.flush();
			out.close();
		}

	}

