import java.io.*;
import java.util.*;

public class Main {
  private static int solve(int n, int[] ds) {
    int[] count = new int[13];
    for (int d : ds) {
      count[d]++;
    }
    if (count[0] >= 1) {
      return 0;
    }
    for (int i = 1; i < 12; i++) {
      if (count[i] >= 3) {
        return 0;
      }
    }
    if (count[12] >= 2) {
      return 0;
    }
    int maxValue = 0;
    for (int i = 0; i < (1 << 11); i++) {
      boolean[] has = new boolean[24];
      has[0] = true;
      if (count[12] > 0) {
        has[12] = true;
      }
      for (int j = 1; j <= 11; j++) {
        if (count[j] == 1) {
          if (((i >> (j - 1)) & 1) == 1) {
            has[j] = true;
          } else {
            has[24 - j] = true;
          }
        } else if (count[j] == 2) {
          has[j] = true;
          has[24 - j] = true;
        }
      }
      List<Integer> list = new ArrayList<>();
      for (int j = 0; j < 24; j++) {
        if (has[j]) {
          list.add(j);
        }
      }
      list.add(24);
      int minDiff = Integer.MAX_VALUE;
      for (int j = 1; j < list.size(); j++) {
        minDiff = Math.min(minDiff, list.get(j) - list.get(j-1));
      }
      maxValue = Math.max(maxValue, minDiff);
    }
    return maxValue;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] ds = reader.nextIntArray(n);
    out.println(solve(n, ds));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
