public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        CTimeGap solver = new CTimeGap();
        solver.solve(1, in, out);
        out.close();
    }

    static class CTimeGap {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            Debug.autoEnable();
            int n = in.ints();
            int[] w = new int[13];
            for (int i = 0; i < n; i++) {
                if (++w[in.ints()] > 2) {
                    out.ans(0).ln();
                    return;
                }
            }

            if (w[0] >= 1 || w[12] > 1) {
                out.ans(0).ln();
                return;
            }

            List<Integer> times = new ArrayList<>();
            int ans = 0;
            for (int i = 0; i < 0b10000_0000_0000; i++) {
                times.clear();
                if (w[12] == 1) {
                    times.add(12);
                }
                for (int j = 1; j < 12; j++) {
                    if (w[j] == 0) {
                    } else if (w[j] == 1) {
                        if ((i & (1 << (j - 1))) == 0) {
                            times.add(j);
                        } else {
                            times.add(24 - j);
                        }
                    } else {
                        times.add(j);
                        times.add(24 - j);
                    }
                }
                int s = 24;
                for (int j = 0; j < times.size(); j++) {
                    for (int k = 0; k < j; k++) {
                        int d = Math.abs(times.get(j) - times.get(k));
                        d = Math.min(d, 24 - d);
                        s = Math.min(s, d);
                    }
                }
                ans = Math.max(ans, s);
            }
            out.ans(ans);
        }

    }

    static class Debug {
        private static final String DEBUG_PROPERTY = "debug";
        private static final String DEBUG_CALL_PATTERN = "^.+\\.debug\\((.+)\\);.*$";
        private static Pattern debugRegex;
        private static boolean enabled = false;
        private static String src;

        public static void enable(String s) {
            enabled = true;
            src = s;
            if (debugRegex == null) {
                debugRegex = Pattern.compile(DEBUG_CALL_PATTERN);
            }
        }

        public static boolean autoEnable() {
            try {
                String s = System.getProperty(DEBUG_PROPERTY);
                if (s != null) {
                    enable(s);
                    return true;
                }
            } catch (AccessControlException ex) {
                src = null;
            }
            return false;
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new BufferedWriter(new OutputStreamWriter(out, Charset.defaultCharset())));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(int i) {
            return ans(Integer.toString(i));
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

    }
