public void solve() {
	int num = ni();
	int d[] = ni(num);
	int cnt[] = new int[13];
	cnt[0] ++;
	for(int i = 0; i < num; i ++) {
		cnt[d[i]] ++;
	}
	if(max(cnt) >= 3 || cnt[0] >= 2 || cnt[12] >= 2) exit(0);
	long max = 0;
	int maxBit = (int)bitFlag(11);
	int allBit = 0;
	boolean b[] = new boolean[25];
	b[0] = true;
	b[24] = true;
	if(cnt[12] == 1) b[12] = true;
	for(int i = 1; i < 12; i ++) {
		if(cnt[i] == 1) allBit |= bitFlag(i);
		if(cnt[i] >= 2) {
			b[i] = true;
			b[24 - i] = true;
		}
	}
	for(int bit = allBit; ; bit = (bit - 1) & allBit) {
		boolean crt[] = new boolean[25];
		for(int i = 0; i < 25; i ++) {
			crt[i] = b[i];
		}
		for(int i = 1; i < 12; i ++) {
			if(cnt[i] == 1) {
				crt[i] = isFlagged(bit, i);
				crt[24 - i] = !isFlagged(bit, i);
			}
		}
		long tmp = INF;
		int prv = 0;
		for(int i = 1; i < 25; i ++) {
			if(crt[i]) {
				tmp = min(tmp, i - prv);
				prv = i;
			}
		}
		max = max(max, tmp);
		if(bit == 0) break;
	}
	prtln(max);
}


	}
