using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        //var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        //Console.SetOut(sw);

        var ans = int.MinValue;
        var N = sc.ReadInt();
        var D = sc.ReadIntArray(N).ToList();
        if (D.Contains(0))
        {
            Console.WriteLine(0);
            return;
        }

        for (int i = 0; i < N; i++)
        {
            for (int j = i + 1; j < N; j++)
            {
                if (D[i] == D[j])
                {
                    var x = Math.Abs(D[i] - (24 - D[i]));
                    ans = Math.Max(ans, x);
                }
            }
        }

        D = D.Distinct().ToList();
        N = D.Count;

        if (N == 1)
        {
            Console.WriteLine(ans);
            return;
        }

        for (int i = 0; i < Math.Pow(2, N); i++)
        {
            var list = new List<int>();
            for (int j = 0; j < N; j++)
            {
                var d = D[j];
                var x = (i >> j) & 1;
                if (x == 1)
                {
                    d = 24 - d;
                }
                list.Add(d);
            }
            var now = int.MaxValue;
            for (int p = 0; p < N; p++)
            {
                for (int q = p + 1; q < N; q++)
                {
                    now = Math.Min(now, Math.Abs(list[p] - list[q]));
                }
            }
            ans = Math.Max(ans, now);
        }
        Console.WriteLine(ans);

        //Console.Out.Flush();
    }
    static Scanner sc = new Scanner();
}

