    static long ans;
    static long[] map = new long[13];
    static void Solve()
    {
        //var NM = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
        var N = long.Parse(Console.ReadLine());
        var D = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
        ans = D.Min();
        for (int i = 0; i < N; i++)
        {
            map[D[i]]++;
        }
        ans = Math.Min(ans, Cul(0, new List<long>()));
        Console.WriteLine(ans);
    }

    static long Cul(int depth,List<long> nums)
    {
        if(depth == 13)
        {
            long tmp = long.MaxValue;
            for (int i = 0; i < nums.Count; i++)
            {
                for (int j = i+1; j < nums.Count; j++)
                {
                    var diff = Math.Abs(nums[i] - nums[j]);
                    diff = Math.Min(24 - diff, diff);
                    tmp = Math.Min(tmp, diff);
                }
            }
            return tmp;
        }
        else
        {
            var next1 = new List<long>(nums);
            var next2 = new List<long>(nums);
            if(map[depth] == 0)
            {
                return Cul(depth + 1, next1);
            }
            else if (map[depth] == 1)
            {
                next1.Add(depth);
                next2.Add(24 - depth);
                return Math.Max(Cul(depth + 1, next1), Cul(depth + 1, next2));
            }
            else if (map[depth] == 2){
                next1.Add(depth);
                next1.Add(24 - depth);
                return Cul(depth + 1, next1);
            }
            else
            {
                return 0;
            }
        }
    }

