                        int t2 = forward[j] ? D[j] : -D[j];
                        int div = Math.Abs(t1 - t2);
                        min = Math.Min(min, Math.Min(div, 24 - div));
                    }
                }
                ans = Math.Max(ans, min);
            }

            Console.WriteLine(ans);
        }


