    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var diffs = new int[13];
            diffs[0] = 1;
            foreach (var d in consoleReader.Split.Int)
                diffs[d]++;

            if (diffs.Any(i => i > 2)) return 0;
            if (diffs[0] > 1) return 0;
            if (diffs[12] > 1) return 0;

            var fix = new List<int>();
            var notFix = new List<int>();
            if (diffs[0] == 1) fix.Add(0);
            if (diffs[12] == 1) fix.Add(12);
            for (int i = 1; i < 12; i++)
            {
                if (diffs[i] > 1)
                {
                    fix.Add(i);
                    fix.Add(24 - i);
                }
                else if (diffs[i] == 1)
                {
                    notFix.Add(i);
                }
            }

            if (notFix.Count == 0)
                return F(new SortedSet<int>(fix));

            var max = 0;
            for (int i = 0; i < (1 << notFix.Count); i++)
            {
                max = Math.Max(G(fix, notFix, i), max);
            }

            return max;
        }
        static int G(List<int> fix, List<int> notFix, int mask)
        {
            var set = new SortedSet<int>(fix);
            for (int i = 0; i < notFix.Count; i++)
            {
                if (((mask >> i) & 1) == 0)
                    set.Add(notFix[i]);
                else
                    set.Add(24 - notFix[i]);
            }
            return F(set);
        }

        static int F(SortedSet<int> set)
        {
            var first = set.First();
            var prev = first;
            var min = 24;
            int diff;
            foreach (var item in set.Skip(1))
            {
                diff = item - prev;
                if (diff > 12) diff = 24 - diff;
                min = Math.Min(diff, min);
                prev = item;
            }
            diff = 24 + first - prev;
            if (diff > 12) diff = 24 - diff;
            return Math.Min(diff, min);
        }


