using System.Threading.Tasks;

namespace AtCorder
{
	public class Program
	{
		static void Main(string[] args)
		{
			var cin = new Scanner2();
			int n = cin.Int();
			if (n == 0) {
				Console.WriteLine(0);
				return;
			}

			int[] d = cin.ArrayInt(n);
			int[] counts = new int[13];
			for (int i = 0; i < n; i++) {
				counts[d[i]]++;
			}

			int ans = 12;
			int left = 0;
			int right = 0;
			bool isLeft = true;
			for (int i = 0; i < 13; i++) {
				if (i == 0) {
					if (counts[i] > 0) {
						ans = 0;
					}
				} else {
					if (counts[i] == 1) {
						if (isLeft) {
							ans = Math.Min(ans, i - left);
							left = i;
							isLeft = false;
						} else {
							ans = Math.Min(ans, i - right);
							right = i;
							isLeft = true;
						}
					} else if (counts[i] > 1) {
						if (i == 12) {
							ans = 0;
						} else {
							ans = Math.Min(ans, i - left);
							ans = Math.Min(ans, i - right);
							left = i;
							right = i;
						}
					}
				}
			}

			ans = Math.Min(ans, Math.Abs(24 - (right + left)));
			Console.WriteLine(ans);
		}
	}

	public class Scanner2
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private string[] buf_;
		private int index_;
		Func<string> reader_;

		public Scanner2(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				reader_ = Console.ReadLine;
			} else {
				filePath_ = file;
				var fs = new StreamReader(file);
				reader_ = fs.ReadLine;
			}
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = reader_();
			while (st == "") {
				st = reader_();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}

		public void Save(string text)
		{
			if (string.IsNullOrWhiteSpace(filePath_)) {
				return;
			}

			File.WriteAllText(filePath_ + "_output.txt", text);
		}
	}
}

using System;
using System.Linq;
