namespace AtCoder
{
    class Program
    {
        static public int[] Sarray() { return ReadLine().Split().Select(int.Parse).ToArray(); }
        static public List<int> Slist() { return ReadLine().Split().Select(int.Parse).ToList(); }

        static void Main(string[] args)
        {
            var N = Slist()[0];
            var D = Slist();
            D.Insert(0, 0);
            D.Sort();
            if (23 < N)
            {
                WriteLine(0);
                return;
            }
            var pos = new int[13];
            for (var i = 0; i < D.Count; ++i)
                ++pos[D[i]];
            if (2 <= pos[0] || 2 <= pos[12])
            {
                WriteLine(0);
                return;
            }
            for (var i = 1; i < 12; ++i)
                if (3 <= pos[i])
                {
                    WriteLine(0);
                    return;
                }

            var org = new int[24];
            for (var i = 0; i <= 12; ++i)
            {
                if (pos[i] == 1)
                    org[i] = 1;
                else if (pos[i] == 2)
                {
                    org[i] = 1;
                    org[24 - i] = 1;
                }
            }
            var maxs = 0;
            for (var k = 0; k < Math.Pow(2, 12); ++k)
            {
                var mins = int.MaxValue;
                var cpy = new int[24];
                org.CopyTo(cpy, 0);
                for (var i = 1; i < 12; ++i)
                    if ((k >> i) != 0)
                    {
                        if (pos[i] == 1)
                        {
                            cpy[i] = 0;
                            cpy[24 - i] = 1;
                        }
                    }

                for (var i = 0; i < 23; ++i)
                    for (var j = i + 1; j < 24; ++j)
                    {
                        if (cpy[i] != 0 && cpy[j] != 0)
                        {
                            var t = j - i;
                            if (12 < t) t = 24 - t;
                            mins = Math.Min(mins, t);
                        }
                    }
                maxs = Math.Max(maxs, mins);
            }
            WriteLine(maxs);
        }
    }
}

using System;
using System.Linq;
using System.Collections.Generic;
using static System.Console;
using System.Text;
using System.IO;

namespace AtCoder
{
    class Program
    {
        static public int[] Sarray() { return ReadLine().Split().Select(int.Parse).ToArray(); }
        static public List<int> Slist() { return ReadLine().Split().Select(int.Parse).ToList(); }

        static int N;
        static List<int> D;
        static int[] mincol;
        static int[,] dp;
        static int maxmins;
        static void Main(string[] args)
        {
            N = Slist()[0];
            D = Slist();
            D.Insert(0, 0);
            mincol = new int[N + 1];
            dp = new int[N + 1, N + 1];
            maxmins = int.MaxValue;
            for (var i = 0; i < N; ++i)
                if (D[i] == 24) D[i] = 0;

            int mini = 0;
            for (var i = 0; i < N; ++i)
            {
                int minc = int.MaxValue;
                for (var j = i + 1; j < N + 1; ++j)
                {
                    dp[i, j] = Math.Abs(D[i] - D[j]);
                    if (dp[i, j] < maxmins)
                    {
                        maxmins = dp[i, j];
                        mini = i;
                    }
                    if (dp[i, j] < minc)
                    {
                        minc = dp[i, j];
                        mincol[i] = j;
                    }
                }
            }
            dfs(1, mini);
            dfs(1, mincol[mini]);
            WriteLine(maxmins);
        }
        static void dfs(int dpt, int ch)
        {
            if (D[ch] == 24 || D[ch] == 0) return;
            //元のを記録しておく
            var dprecol = new int[dp.GetLength(0)];
            for (var i = 0; i < dp.GetLength(0); ++i)
                dprecol[i] = dp[i, ch];
            var dprerow = new int[dp.GetLength(1)];
            for (var i = 0; i < dp.GetLength(1); ++i)
                dprerow[i] = dp[ch, i];
            var mincolpre = new int[mincol.Length];
            Array.Copy(mincol, mincolpre, mincol.Length);

            D[ch] = 24 - D[ch];
            //24-Dに変更したのでその分を更新
            //行について
            int s = int.MaxValue;
            for (var i = ch + 1; i < N + 1; ++i)
            {
                dp[ch, i] = Math.Abs(D[ch] - D[i]);
                if (dp[ch, i] < s)
                {
                    s = dp[ch, i];
                    mincol[ch] = i;
                }
            }
            //列について
            for (var i = 0; i < ch; ++i)
            {
                dp[i, ch] = Math.Abs(D[ch] - D[i]);
                if (mincol[i] != ch)
                {
                    if (dp[i, ch] < dp[i, mincol[i]])
                        mincol[i] = ch;
                }
                else
                {
                    s = int.MaxValue;
                    for (var j = i + i; j < N + 1; ++j)
                        if (dp[i, j] < s)
                            mincol[i] = j;
                }
            }
            var min = int.MaxValue;
            int mini = 0, minj = 0;
            for (var i = 0; i < N; ++i)
                if (dp[i, mincol[i]] < min)
                {
                    mini = i;
                    minj = mincol[i];
                    min = dp[i, mincol[i]];
                }

            if (maxmins < min)
            {
                maxmins = min;
                var cha = Math.Abs(D[mini] + D[minj] - 24);
                if (maxmins < cha)
                {
                    if (maxmins < 24 - D[mini])
                        dfs(dpt + 1, mini);
                    if (maxmins < 24 - D[minj])
                        dfs(dpt + 1, minj);
                }
            }
            //元に戻す
            D[ch] = 24 - D[ch];
            for (var i = 0; i < dp.GetLength(0); ++i)
                dp[i, ch]=dprecol[i];
            for (var i = 0; i < dp.GetLength(1); ++i)
                dp[ch, i] = dprerow[i];
            Array.Copy(mincolpre, mincol, mincolpre.Length);

        }
    }
}

