static class mymath
{
    public static long Mod = 1000000007;
    public static bool isprime(long a) {
        if (a < 2) return false;
        for (long i = 2; i * i <= a; i++) if (a % i == 0) return false;
        return true;
    }
    public static bool[] sieve(int n) {
        var p = new bool[n + 1];
        for (int i = 2; i <= n; i++) p[i] = true;
        for (int i = 2; i * i <= n; i++) if (p[i]) for (int j = i * i; j <= n; j += i) p[j] = false;
        return p;
    }
    public static List<int> getprimes(int n) {
        var prs = new List<int>();
        var p = sieve(n);
        for (int i = 2; i <= n; i++) if (p[i]) prs.Add(i);
        return prs;
    }
    public static long[][] E(int n) {
        var ret = new long[n][];
        for (int i = 0; i < n; i++) { ret[i] = new long[n]; ret[i][i] = 1; }
        return ret;
    }
    public static double[][] dE(int n) {
        var ret = new double[n][];
        for (int i = 0; i < n; i++) { ret[i] = new double[n]; ret[i][i] = 1; }
        return ret;
    }
    public static long[][] pow(long[][] A, long n) {
        if (n == 0) return E(A.Length);
        var t = pow(A, n / 2);
        if ((n & 1) == 0) return mul(t, t);
        return mul(mul(t, t), A);
    }
    public static double[][] pow(double[][] A, long n) {
        if (n == 0) return dE(A.Length);
        var t = pow(A, n / 2);
        if ((n & 1) == 0) return mul(t, t);
        return mul(mul(t, t), A);
    }
    public static double dot(double[] x, double[] y) {
        int n = x.Length;
        double ret = 0;
        for (int i = 0; i < n; i++) ret += x[i] * y[i];
        return ret;
    }
    public static double _dot(double[] x, double[] y) {
        int n = x.Length;
        double ret = 0, r = 0;
        for (int i = 0; i < n; i++) {
            double s = ret + (x[i] * y[i] + r);
            r = (x[i] * y[i] + r) - (s - ret);
            ret = s;
        }
        return ret;
    }
    public static long dot(long[] x, long[] y) {
        int n = x.Length;
        long ret = 0;
        for (int i = 0; i < n; i++) ret = (ret + x[i] * y[i]) % Mod;
        return ret;
    }
    public static T[][] trans<T>(T[][] A) {
        int n = A[0].Length, m = A.Length;
        var ret = new T[n][];
        for (int i = 0; i < n; i++) { ret[i] = new T[m]; for (int j = 0; j < m; j++) ret[i][j] = A[j][i]; }
        return ret;
    }
    public static double[] mul(double[][] A, double[] x) {
        int n = A.Length;
        var ret = new double[n];
        for (int i = 0; i < n; i++) ret[i] = dot(x, A[i]);
        return ret;
    }
    public static long[] mul(long[][] A, long[] x) {
        int n = A.Length;
        var ret = new long[n];
        for (int i = 0; i < n; i++) ret[i] = dot(x, A[i]);
        return ret;
    }
    public static long[][] mul(long[][] A, long[][] B) {
        int n = A.Length;
        var Bt = trans(B);
        var ret = new long[n][];
        for (int i = 0; i < n; i++) ret[i] = mul(Bt, A[i]);
        return ret;
    }
    public static double[][] mul(double[][] A, double[][] B) {
        int n = A.Length;
        var Bt = trans(B);
        var ret = new double[n][];
        for (int i = 0; i < n; i++) ret[i] = mul(Bt, A[i]);
        return ret;
    }
    public static long[] add(long[] x, long[] y) {
        int n = x.Length;
        var ret = new long[n];
        for (int i = 0; i < n; i++) ret[i] = (x[i] + y[i]) % Mod;
        return ret;
    }
    public static long[][] add(long[][] A, long[][] B) {
        int n = A.Length;
        var ret = new long[n][];
        for (int i = 0; i < n; i++) ret[i] = add(A[i], B[i]);
        return ret;
    }
    public static long pow(long a, long b) {
        if (a >= Mod) return pow(a % Mod, b);
        if (a == 0) return 0;
        if (b == 0) return 1;
        var t = pow(a, b / 2);
        if ((b & 1) == 0) return t * t % Mod;
        return t * t % Mod * a % Mod;
    }
    public static long inv(long a) => pow(a, Mod - 2);
    public static long gcd(long a, long b) {
        while (b > 0) { var t = a % b; a = b; b = t; } return a;
    }
    // a x + b y = gcd(a, b)
    public static long extgcd(long a, long b, out long x, out long y) {
        long g = a; x = 1; y = 0;
        if (b > 0) { g = extgcd(b, a % b, out y, out x); y -= a / b * x; }
        return g;
    }
    public static long lcm(long a, long b) => a / gcd(a, b) * b;

    static long[] facts;
    public static long[] setfacts(int n) {
        facts = new long[n + 1];
        facts[0] = 1;
        for (int i = 0; i < n; i++) facts[i + 1] = facts[i] * (i + 1) % Mod;
        return facts;
    }
    public static long comb(int n, int r) {
        if (n < 0 || r < 0 || r > n) return 0;
        if (n - r < r) r = n - r;
        if (r == 0) return 1;
        if (r == 1) return n;
        if (facts != null && facts.Length > n) return facts[n] * inv(facts[r]) % Mod * inv(facts[n - r]) % Mod;
        int[] numer = new int[r], denom = new int[r];
        for (int k = 0; k < r; k++) { numer[k] = n - r + k + 1; denom[k] = k + 1; }
        for (int p = 2; p <= r; p++) {
            int piv = denom[p - 1];
            if (piv > 1) {
                int ofst = (n - r) % p;
                for (int k = p - 1; k < r; k += p) { numer[k - ofst] /= piv; denom[k] /= piv; }
            }
        }
        long ret = 1;
        for (int k = 0; k < r; k++) if (numer[k] > 1) ret = ret * numer[k] % Mod;
        return ret;
    }
    public static long[][] getcombs(int n) {
        var ret = new long[n + 1][];
        for (int i = 0; i <= n; i++) {
            ret[i] = new long[i + 1];
            ret[i][0] = ret[i][i] = 1;
            for (int j = 1; j < i; j++) ret[i][j] = (ret[i - 1][j - 1] + ret[i - 1][j]) % Mod;
        }
        return ret;
    }
    // nC0, nC2, ..., nCn
    public static long[] getcomb(int n) {
        var ret = new long[n + 1];
        ret[0] = 1;
        for (int i = 0; i < n; i++) ret[i + 1] = ret[i] * (n - i) % Mod * inv(i + 1) % Mod;
        return ret;
    }
}

using System;
using System.Linq;
using System.Collections.Generic;
using static System.Console;
using System.Text;
using System.IO;

namespace AtCoder
{
    class Program
    {
        static public int[] Sarray() { return ReadLine().Split().Select(int.Parse).ToArray(); }
        static public List<int> Slist() { return ReadLine().Split().Select(int.Parse).ToList(); }

        static int N;
        static List<int> D;
        static int[] mincol;
        static int[,] dp;
        static int maxmins;
        static void Main(string[] args)
        {
            N = Slist()[0];
            D = Slist();
            D.Insert(0, 0);
            mincol = new int[N + 1];
            dp = new int[N + 1, N + 1];
            maxmins = int.MaxValue;

            int mini = 0;
            for (var i = 0; i < N; ++i)
            {
                int minc = int.MaxValue;
                for (var j = i + 1; j < N + 1; ++j)
                {
                    var t = Math.Abs(D[i] - D[j]);
                    dp[i, j] = t <= 12 ? t : 24 - t;
                    if (dp[i, j] < maxmins)
                    {
                        maxmins = dp[i, j];
                        mini = i;
                    }
                    if (dp[i, j] < minc)
                    {
                        minc = dp[i, j];
                        mincol[i] = j;
                    }
                }
            }
            var status = new bool[N + 1];
            dfs(1, mini, status);
            dfs(1, mincol[mini], status);
            WriteLine(maxmins);
        }
        static void dfs(int dpt, int ch, bool[] status)
        {
            if (status[ch]) return;
            status[ch] = true;
            //元のを記録しておく
            var dprecol = new int[dp.GetLength(0)];
            for (var i = 0; i < dp.GetLength(0); ++i)
                dprecol[i] = dp[i, ch];
            var dprerow = new int[dp.GetLength(1)];
            for (var i = 0; i < dp.GetLength(1); ++i)
                dprerow[i] = dp[ch, i];
            var mincolpre = new int[mincol.Length];
            Array.Copy(mincol, mincolpre, mincol.Length);

            D[ch] = 24 - D[ch];
            //24-Dに変更したのでその分を更新
            //行について
            int s = int.MaxValue;
            for (var i = ch + 1; i < N + 1; ++i)
            {
                var t = Math.Abs(D[ch] - D[i]);
                dp[ch, i] = t <= 12 ? t : 24 - t;
                if (dp[ch, i] < s)
                {
                    s = dp[ch, i];
                    mincol[ch] = i;
                }
            }
            //列について
            for (var i = 0; i < ch; ++i)
            {
                var t = Math.Abs(D[ch] - D[i]);
                dp[i, ch] = t <= 12 ? t : 24 - t;
                if (mincol[i] != ch)
                {
                    if (dp[i, ch] < dp[i, mincol[i]])
                        mincol[i] = ch;
                }
                else
                {
                    s = int.MaxValue;
                    for (var j = i + 1; j < N + 1; ++j)
                        if (dp[i, j] < s)
                        {
                            s = dp[i, j];
                            mincol[i] = j;
                        }
                }
            }
            var min = int.MaxValue;
            int mini = 0, minj = 0;
            for (var i = 0; i < N; ++i)
                if (dp[i, mincol[i]] < min)
                {
                    mini = i;
                    minj = mincol[i];
                    min = dp[i, mincol[i]];
                }

            if (maxmins <= min)
            {
                maxmins = min;
                var cha = Math.Abs(D[mini] + D[minj] - 24);
                if (maxmins < cha)
                {
                    if (maxmins < 24 - D[mini])
                        dfs(dpt + 1, mini, status);
                    if (maxmins < 24 - D[minj])
                        dfs(dpt + 1, minj, status);
                }
            }
            //元に戻す
            status[ch] = false;
            D[ch] = 24 - D[ch];
            for (var i = 0; i < dp.GetLength(0); ++i)
                dp[i, ch] = dprecol[i];
            for (var i = 0; i < dp.GetLength(1); ++i)
                dp[ch, i] = dprerow[i];
            Array.Copy(mincolpre, mincol, mincolpre.Length);

        }
    }
}

