        static List<int> D;
        static int[] mincol;
        static int[,] dp;
        static int maxmins;
        static void Main(string[] args)
        {
            N = Slist()[0];
            D = Slist();
            D.Insert(0, 0);
            mincol = new int[N + 1];
            dp = new int[N + 1, N + 1];
            maxmins = int.MaxValue;

            int mini = 0;
            for (var i = 0; i < N; ++i)
            {
                int minc = int.MaxValue;
                for (var j = i + 1; j < N + 1; ++j)
                {
                    var t = Math.Abs(D[i] - D[j]);
                    dp[i, j] = t <= 12 ? t : 24 - t;
                    if (dp[i, j] < maxmins)
                    {
                        maxmins = dp[i, j];
                        mini = i;
                    }
                    if (dp[i, j] < minc)
                    {
                        minc = dp[i, j];
                        mincol[i] = j;
                    }
                }
            }
            dfs(1, mini);
            dfs(1, mincol[mini]);
            WriteLine(maxmins);
        }
        static void dfs(int dpt, int ch)
        {
            //元のを記録しておく
            var dprecol = new int[dp.GetLength(0)];
            for (var i = 0; i < dp.GetLength(0); ++i)
                dprecol[i] = dp[i, ch];
            var dprerow = new int[dp.GetLength(1)];
            for (var i = 0; i < dp.GetLength(1); ++i)
                dprerow[i] = dp[ch, i];
            var mincolpre = new int[mincol.Length];
            Array.Copy(mincol, mincolpre, mincol.Length);

            D[ch] = 24 - D[ch];
            //24-Dに変更したのでその分を更新
            //行について
            int s = int.MaxValue;
            for (var i = ch + 1; i < N + 1; ++i)
            {
                var t = Math.Abs(D[ch] - D[i]);
                dp[ch, i] = t <= 12 ? t : 24 - t;
                if (dp[ch, i] < s)
                {
                    s = dp[ch, i];
                    mincol[ch] = i;
                }
            }
            //列について
            for (var i = 0; i < ch; ++i)
            {
                var t = Math.Abs(D[ch] - D[i]);
                dp[i, ch] = t <= 12 ? t : 24 - t;
                if (mincol[i] != ch)
                {
                    if (dp[i, ch] < dp[i, mincol[i]])
                        mincol[i] = ch;
                }
                else
                {
                    s = int.MaxValue;
                    for (var j = i + i; j < N + 1; ++j)
                        if (dp[i, j] < s)
                            mincol[i] = j;
                }
            }
            var min = int.MaxValue;
            int mini = 0, minj = 0;
            for (var i = 0; i < N; ++i)
                if (dp[i, mincol[i]] < min)
                {
                    mini = i;
                    minj = mincol[i];
                    min = dp[i, mincol[i]];
                }

            if (maxmins < min)
            {
                maxmins = min;
                var cha = Math.Abs(D[mini] + D[minj] - 24);
