public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int[] D = new int[N + 1];  // D[N] = 0
		for(int i = 0; i < N; i++)
			D[i] = GetInt();

		int[] cnt = new int[13];
		for(int i = 0; i <= N; i++)
			cnt[D[i]]++;

		var free = new List<int>();
		bool[] exist = new bool[24];
		exist[0] = true;
		for(int i = 0; i < N; i++)
		{
			if(cnt[D[i]] >= 3)
			{
				Console.WriteLine(0);
				return;
			}
			else if(cnt[D[i]] == 2)
			{
				if(D[i] == 0 || D[i] == 12)
				{
					Console.WriteLine(0);
					return;
				}
				else
				{
					exist[D[i]] = true;
					exist[24 - D[i]] = true;
				}
			}
			else if(cnt[D[i]] == 1)
				free.Add(i);
		}

		int ans = 0;
		int L = free.Count;
		for(int s = 0; s < (1 << L); s++)
		{
			bool[] tmpExist = new bool[24];
			Array.Copy(exist, tmpExist, 24);

			for(int i = 0; i < L; i++)
			{				
				if(contain(s, i))
					tmpExist[D[free[i]]] = true;
				else
					tmpExist[24 - D[free[i]]] = true;				
			}

			int min = int.MaxValue;
			for(int i = 0; i < 24; i++)
			{
				for(int j = i + 1; j < 24; j++)
				{
					if(tmpExist[i] && tmpExist[j])
						min = Math.Min(min, Math.Min(j - i, 24 - (j - i)));
				}
			}
			ans = Math.Max(ans, min);
		}

		Console.WriteLine(ans);
	}

	private bool contain(int s, int x) => ((s >> x) & 1) == 1;
}


