	public static long BS<T>(Func<long,T> seq, T value)  where T : IComparable<T> {
		long left = -1;
		long right = 25;
		while (right - left > 1) {
			long mid = left + (right - left) / 2;
			if (0<=seq(mid).CompareTo(value)) right = mid;
			else left = mid;
		}
		return right;
