	defer Flush()
	N := readi()
	D := make([]int, N)
	for i := range D {
		D[i] = readi()
	}

	var ans int
	for i := range D {
		tmp := 25
		for _, v := range D {
			tmp = min(tmp, v)
		}
		d := make([]int, N)
		for j := range D {
			d[j] = D[j]
			if i == j {
				d[j] = 24 - D[j]
			}
		}
		for j, v := range d {
			for k := j + 1; k < len(d); k++ {
				u := d[k]
				s := abs(u - v)
				s = min(s, 24-s)
				tmp = min(tmp, s)
			}
		}
		ans = max(ans, tmp)
	}
	println(ans)

}

