				if !b[i] {
					arr = append(arr, i)
				} else {
					arr = append(arr, (24-i)%24)
				}
			} else {
				arr = append(arr, i, (24-i)%24)
			}
		}

		mi := 24
		for i := 0; i < len(arr); i++ {
			for j := i+1; j < len(arr); j++ {
				d := abs(arr[i]-arr[j])
				mi = min(mi, min(24-d,d))
			}
		}
		s = max(s, mi)
	})

	fmt.Fprintln(wr, s)
	wr.Flush()
