	sc.Buffer(make([]byte, 0), 1000000001*3)
	sc.Split(bufio.ScanWords)
	n := nextInt()
	div := make([]int, 13)
	div[0]++
	for i := 0; i < n; i++ {
		d := nextInt()
		div[d]++
	}

	if div[0] >= 2 || div[12] >= 2 {
		fmt.Println(0)
		return
	}
	for j := 1; j <= 11; j++ {
		if div[j] >= 3 {
			fmt.Println(0)
			return
		}
	}

	pattern := make(map[int]int, 0)
	bits := 1 << 12
	for p := 0; p < bits; p++ {
		contestants := 1
		if div[12] == 1 {
			contestants = contestants | 1<<12
		}
		for d := 1; d < 12; d++ {
			if div[d] == 2 {
				contestants = contestants | 1<<uint(d)
				contestants = contestants | 1<<uint(24-d)
				continue
			}
			if div[d] == 0 {
				continue
			}
			switch {
			case p>>uint(d)&1 == 1:
				contestants = contestants | 1<<uint(d)
			default:
				contestants = contestants | 1<<uint(24-d)
			}
		}
		pattern[contestants] = 12
	}

	for c := range pattern {
		cArray := make([]int, 0)
		for d := 0; d < 24; d++ {
			if c>>uint(d)&1 == 1 {
				cArray = append(cArray, d)
			}
		}
		for i := 0; i < len(cArray); i++ {
			for j := i + 1; j < len(cArray); j++ {
				switch {
				case cArray[j]-cArray[i] > 12:
					if 24-(cArray[j]-cArray[i]) < pattern[c] {
						pattern[c] = 24 - (cArray[j] - cArray[i])
					}
				default:
					if cArray[j]-cArray[i] < pattern[c] {
						pattern[c] = cArray[j] - cArray[i]
					}
				}
			}
		}
	}

	ans := 0
	for _, v := range pattern {
		if v > ans {
			ans = v
		}
	}
	fmt.Println(ans)
}

