func calc(t []int) int {
	ret := 24
	cur := 0
	for i := 1; i < 24; i++ {
		if t[i] == 1 {
			x := i - cur
			ret = min(ret, x)
			cur = i
		}
	}
	ret = min(ret, 24-cur)
	return ret
}

func main() {
