//•*¨*•.¸¸♪Main•*¨*•.¸¸♪(　-ω-)ノ　(　・ω・)

func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, 10000), 1001001)
	defer wr.Flush()

	n := scanInt()
	a := scanInts(n)

	cnt := make([]int, 13)
	cnt[0]++
	for _, e := range a {
		cnt[e]++
	}

	for i := 0; i < 13; i++ {
		if cnt[i] > 2 || (cnt[i] > 1 && (i == 0 || i == 12)) {
			fmt.Fprintln(wr, 0)
			return
		}
	}

	s := 0
	bitExhaustiveSearch(13, func(b []bool) {
		arr := []int{}
		for i := 0; i < 13; i++ {
			if cnt[i] == 0 {
				continue
			}
			if cnt[i] == 1 {
				if !b[i] {
					arr = append(arr, i)
				} else {
					arr = append(arr, (24-i)%24)
				}
			} else {
				arr = append(arr, i, (24-i)%24)
			}
		}

		mi := 24
		for i := 0; i < len(arr); i++ {
			for j := i+1; j < len(arr); j++ {
				d := abs(arr[i]-arr[j])
				mi = min(mi, min(24-d,d))
			}
		}
		s = max(s, mi)
	})

	fmt.Fprintln(wr, s)
}

func bitExhaustiveSearch(n int, fn func(a []bool)) {
	all := 1 << uint(n)
	a := make([]bool, n)
	for i := 0; i < all; i++ {
		for j := 0; j < n; j++ {
			if i >> uint(j) & 1 == 1 { a[j] = true } else { a[j] = false }
		}
		fn(a)
	}
}

