			mnt = min(mnt, abs(i-t))
			mnu = min(mnu, abs(i-u))
		}
		i := t
		v := mnt
		if mnt < mnu {
			i = u
			v = mnu
		}
		x[i] = true
		ans = min(ans, v)
	}
	return ans
