        auto ss = s.dup;
        if (cnt[i] > 1) {
            ss ~= [i, 24 - i];
            dfs(i + 1, ss);
        }
        else if (cnt[i] == 1) {
            auto ssa = ss.dup ~ [i];
            dfs(i + 1, ssa);
            auto ssb = ss.dup ~ [24 - i];
            dfs(i + 1, ssb);
        }
        else {
            dfs(i + 1, ss);
        }
    }

    dfs(1, [0, 24]);

    writeln(ans);
}



