void main() {
    int N; scanln(N);
    int K = 24;
    int[] ds = readln.split.to!(int[]).sort!"a<b".array;

    if (ds.group.map!"a[1]".canFind!"a>2") {
        0.writeln;
        return;
    }
    assert(ds.length <= K);

    new Generator!int({
        int[] ds1 = ds.group.filter!"a[1]==1".map!"a[0]".array;
        int[] ds2 = ds.group.filter!"a[1]==2".map!"a[0]".array;
        int M = ds1.length.to!int;

        int[] as = new int[K];
        auto list = DList!int();
        foreach(bits; 0..2^^M) {
            as[] = 0;
            as[K/2]++;
            foreach(i, d; ds1) {
                as[(K/2 + (bits>>i&1 ? 1:-1)*d)%K]++;
            }
            foreach(i, d; ds2) {
                as[(K/2 + d)%K]++;
                as[(K/2 - d)%K]++;
            }

            list.clear;
            as.enumerate.each!(
                a => a.value.times!(
                    () => list.insertBack(a.index.to!int)
                )
            );
            as.enumerate.each!(
                a => a.value.times!(
                    () => list.insertBack(a.index.to!int + K)
                )
            );
            int[] xs = list[].array;
            zip(xs[0..$-1], xs[1..$]).map!"a[1]-a[0]".reduce!min.yield;
        }
    }).reduce!max.writeln;
}

