	for(int i = 0; i <= n; i++){
		for(int j = i + 1; j <= n; j++){
			int Gap = abs(timeGap[i] - timeGap[j]);
			Gap = min(Gap, 24 - Gap);
			minimum = min(minimum, Gap);
		}
	}
	// cout << "ans:";
	// for(int i = 0; i <= n; i++){
	// 	cout << timeGap[i] << " ";
	// }
