void dfs(int k){
	for(int i = 1; i <= D[k][0]; i++){
		timeGap[k] = D[k][i];
		if(k == n){
			int minimum = 0;
			minimum = getMin();
			ans = max(ans, minimum);
		}
		else dfs(k + 1);
	}
}
