def solve(n, ds):
    if n > 24: return 0
    if max([ds.count(v) for v in range(13)]) >= 3:
        return 0
    if ds.count(0) > 0: return 0
    if ds.count(12) > 1: return 0
    if n > 12: return 1

    res = 0
    for mask in range(1<<n):
        pos = ds[::]
        s = 24
        for i in range(n):
            if mask & 1<<i:
                pos[i] = 24 - pos[i]
        for i in range(n):
            for j in range(i):
                s = min(s, abs(pos[i] - pos[j]), 24 - abs(pos[i] - pos[j]))
        res = max(res, s)
    return res

