def calc(F):    
    res = 0
    for f in F:
        S = format(f, "024b")[24:1:-1]

        count = 12
        tmp = 1
        for s in S:
            if s == "1":
                count = min(count, tmp)
                tmp = 1
            else:
                tmp += 1

        res = max(res, count)
    return res


def g(D, F):
    if len(D) == 0:
        return calc(F)

    d = D[0]
    s = set()
    for f in F:
        r = 2 ** d
        if f & r == 0:
            s.add(f + r)

        r = 2 ** (24 - d)
        if f & r == 0:
            s.add(f + r)

    return g(D[1:], s)


