def solve(n, d):
    if n >= 24:
        return 0

    cnt = {i: 0 for i in range(12 + 1)}
    cnt[0] = 1
    for dd in d:
        cnt[dd] += 1

    # 同じ時刻の都市が存在する場合、
    # 時刻の差の最小値は、0になる
    # 鳩ノ巣
    if cnt[0] > 1:
        return 0
    elif cnt[12] > 1:
        return 0
    else:
        for i in range(1, 12):
            if cnt[i] > 2:
                return 0

    bit_cnt = 0
    for i in range(1, 12):
        if cnt[i] == 1:
            bit_cnt += 1

    res = -1
    for mask in range(1 << bit_cnt):
        t = [False] * 24
        t[0] = True

        cur = 0
        for i in range(1, 12):
            if cnt[i] == 1:
                if (mask >> cur) & 1 == 1:
                    t[i] = True
                else:
                    t[24 - i] = True
                cur += 1
            elif cnt[i] == 2:
                t[i] = True
                t[24 - i] = True

        if cnt[12] == 1:
            t[12] = True

        # print(*map(lambda x: 1 if x else '-', t))

        dist = 24
        frm = 0
        for i in range(1, 48 + 1):
            if t[i % 24]:
                dist = min(dist, (i - frm) % 24)
                frm = i

        res = max(res, dist)

    return res


