    for mask in range(1<<n):
        pos = ds[::]
        s = 24
        for i in range(n):
            if mask & 1<<i:
                pos[i] = 24 - pos[i]
        pos.append(0)
        for i in range(n):
            for j in range(i):
                s = min(s, abs(pos[i] - pos[j]), 24 - abs(pos[i] - pos[j]))
        res = max(res, s)
    return res

