            times.append(k)
            times.append(24 - k)
        else:
            undecided.append(k)

    ans = 0
    n = len(undecided)
    for pattern in range(2 ** n):
        tmp = copy.deepcopy(times)
        for i in range(n):
            if pattern & (1 << i):
                tmp.append(undecided[i])
            else:
                tmp.append(24 - undecided[i])

        L = len(tmp)
        diff = INF
        for i in range(L):
            for j in range(i + 1, L):
                d = abs(tmp[i] - tmp[j])
                d = min(d, 24 - d)

                if d < diff:
                    diff = d

        if diff > ans:
            ans = diff

    print(ans)


