    }
    let mut p = vec![];
    for i in 0..n+1 {
        for j in i+1..n+1 {
            let mut acc = vec![];
            for k in 0..2 {
                for l in 0..2 {
                    let delta = (d2[i][k] - d2[j][l]).abs();
                    acc.push( min(delta, 24 - delta));
                }
            }
            acc.sort();
            p.push(acc[acc.len()-1]);
        }
    }
    p.sort();
    println!("{}", p[0]);
}

