fn main() {
    input! {
        n: usize,
        dd: [usize; n]
    }

    let mut map = HashMap::new();
    for d in dd {
        *map.entry(d).or_insert(0) += 1;
    }

    let mut ans = 0;

    for i in 0..1<<map.len() {
        let mut times = vec![0, 24];
        for (j, (&key, &val)) in map.iter().enumerate() {
            if val > 2 {
                println!("0");
                return;
            } else if val == 2 {
                times.push(key);
                times.push(24-key);
            } else {
                if i & 1<<j == 1<<j {
                    times.push(24-key);
                } else {
                    times.push(key);
                }
            }
        }
        ans = std::cmp::max(ans, min_time(times));
    }

    println!("{}", ans);
}

fn min_time(mut times: Vec<usize>) -> usize {
    times.sort();

    let mut min = 12;

    for i in 0..times.len()-1 {
        let sub = times[i+1] - times[i];
        min = std::cmp::min(min, sub);
    }
    min
}

