    for i in 0..13 {
        m.insert(i, 0);
    }
    *m.entry(0).or_insert(0) += 1;
    for i in 0..n {
        *m.entry(d[i]).or_insert(0) += 1;
        if m[&d[i]] > 2 {
            println!("{}", 0);
            return;
        }
    }

    // dbg!(&m);

    if m[&0] > 1 || m[&12] > 1 {
        println!("{}", 0);
        return;
    }

    let p = 1 << 11;
    // bit全探索
    let mut ans = 0;
    for i in 0..p {
        let mut v = vec![0];
        if m[&12] > 0 {
            v.push(12);
        }
        // 0から11について、個数が1個ならiか、24-iのどちらかを追加する
        for j in 0..11 {
            if m[&(j + 1)] == 0 {
                continue;
            }
            if m[&(j + 1)] == 2 {
                v.push(j + 1);
                v.push(24 - (j + 1));
                continue;
            }
            if i >> j & 1 == 1 {
                v.push(j + 1);
            } else {
                v.push(24 - (j + 1));
            }
        }
        v.sort();
        //dbg!(&v);
        let mut a = 24;
        for k in 0..v.len() - 1 {
            a = min(a, v[k + 1] - v[k]);
        }
        ans = max(a, ans);
    }
    println!("{}", ans);
}

