    for v in data {
        dt[v as usize] += 1;
    }
    if dt[0] >= 1 || dt[12] >= 2 {
        println!("0");
        return;
    }
    for &x in &dt {
        if x >= 3 {
            println!("0");
            return;
        }
    }

    let mut ans = 0;
    for i in 0..(1 << 11) {
        let mut dd = [false; 24];
        dd[0] = true;
        for (x, &y) in dt.iter().enumerate() {
            if y == 1 && (x == 0 || x == 12) {
                dd[x] = true;
