                dd[x] = true;
                dd[24 - x] = true;
            } else if y == 1 {
                if (i >> (x - 1)) & 1 != 0 {
                    dd[x] = true;
                } else {
                    dd[24 - x] = true;
                }
            }
        }

        let mut start: i32 = -1;
        let mut last: i32 = -1;
        let mut min_gap: i32 = 24;
        for (x, &y) in dd.iter().enumerate() {
            if !y {
                continue;
            }
            if start == -1 {
                start = x as i32;
            } else {
                min_gap = min2(min_gap, x as i32 - last);
            }
            last = x as i32;
        }
        min_gap = min2(min_gap, (start + 24) - last);
        ans = max2(ans, min_gap);
    }

    println!("{}", ans);
}

