fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n = sc.read();
    let d: Vec<usize> = (0..n).map(|_| sc.read()).collect();
    let mut cnt = vec![0; 13];
    for &d in &d {
        cnt[d] += 1;
    }
    let cnt = cnt;

    let mut ext = vec![false; 24];

    if cnt[0] > 0 || cnt[12] > 1 {
        return "0\n".to_string();
    }
    ext[0] = true;
    ext[12] = cnt[12] > 0;

    for i in 1..12 {
        if cnt[i] > 2 {
            return "0\n".to_string();
        }
        ext[i] = cnt[i] > 0;
        ext[24 - i] = cnt[i] > 1;
    }

    let mut ret = 0;
    for s in 0..1 << 11 {
        for k in 1..12 {
            if s&(1<<(k-1)) != 0 && ext[k] && !ext[24-k] {
                ext[k] = false;
                ext[24-k] = true;
            }
            if s&(1<<(k-1)) == 0 && !ext[k] && ext[24-k] {
                ext[k] = true;
                ext[24-k] = false;
            }
        }
        let mut r = 12;
        for dis in (1..12).rev() {
            for i in 0..24 {
                if ext[i] && ext[(i+dis)%24] {
                    r = dis;
                }
            }
        }
        ret = std::cmp::max(ret, r);
    }

    format!("{}\n", ret)
}
