fn dfs(mut clocks: Vec<i64>, pos: usize, mindiff: i64, d: &[i64]) -> bool {
    if pos == d.len() {
        return true;
    }

    let mut res = false;
    for &clock in &[d[pos], 24 - d[pos]] {
        if clocks.iter().take(pos).all(|c| diff(*c, clock) >= mindiff) {
            clocks[pos] = clock;
            res = dfs(clocks.clone(), pos+1, mindiff, d) || res;
        }
    }
    res
}

fn diff(a: i64, b: i64) -> i64 {
    min((a-b).abs(), 24-(a-b).abs())
}

