    for _ in 0..n {
        let x: usize = sc.read();
        count[x] += 1;
        if x == 0 {
            println!("0");
            return;
        }
    }

    let mut fixed = vec![];
    let mut floating = vec![];
    for i in 1..13 {
        if count[i] >= 3 {
            println!("0");
            return;
        }
        if count[i] == 2 {
            if i == 12 {
                println!("0");
                return;
            }
            fixed.push(12 - i);
            fixed.push(i + 12);
        }
        if count[i] == 1 {
            if i == 12 {
                fixed.push(0);
            } else {
                floating.push(i);
            }
        }
    }

    let n = floating.len();

    let mut ans = 0;
    for mask in 0..(1 << n) {
        let mut v = fixed.clone();
        for i in 0..n {
            if mask & (1 << i) != 0 {
                v.push(12 + floating[i]);
