const INF: i64 = 1 << 60;

fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin.bytes().map(|c| c.unwrap() as char));
    let N: usize = sc.get();
    let mut D: Vec<i64> = sc.vec(N);
    D.sort();
    let mut cur = 0;
    let mut double = HashSet::new();
    while cur < N {
        let now = D[cur];
        let mut cnt = 0;
        while cur < N && now == D[cur] {
            cnt += 1;
            cur += 1;
        }
        if cnt == 2 {
            double.insert(now);
        } else if cnt >= 3 {
            println!("0");
            return;
        }
    }
    let D: Vec<i64> = D.into_iter().collect::<HashSet<i64>>().into_iter().collect();
    let N = D.len();
    let mut ans = 0;
    for bit in 0..1<<N {
        let mut times = BTreeSet::new();
        times.insert(24);
        for i in 0..N {
            if double.contains(&D[i]) {
                times.insert(24-D[i]);
                times.insert(D[i]);
            } else if D[i] == 0 {
                times.insert(D[i]);
            } else if (bit>>i) & 1 != 0 {
                times.insert(24-D[i]);
            } else {
                times.insert(D[i]);
            }
        }
        let mut s = INF;
        let mut prev = 0;
        for &time in &times {
            s = min(s, (time - prev).abs());
            prev = time;
        }
        ans = max(ans, s);
    }
    println!("{}", ans);
}

use std::cmp;
