fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let mut count = vec![0; 12 + 1];
    count[0] = 1;
    for _ in 0..n {
        let x: usize = sc.read();
        count[x] += 1;
        if x == 0 {
            println!("0");
            return;
        }
    }

    let mut fixed = vec![12];
    let mut floating = vec![];
    for i in 1..13 {
        if count[i] >= 3 {
            println!("0");
            return;
        }
        if count[i] == 2 {
            if i == 12 {
                println!("0");
                return;
            }
            fixed.push(12 - i);
            fixed.push(i + 12);
        }
        if count[i] == 1 {
            if i == 12 {
                fixed.push(0);
            } else {
                floating.push(i);
            }
        }
    }

    let n = floating.len();

    let mut ans = 0;
    for mask in 0..(1 << n) {
        let mut v = fixed.clone();
        for i in 0..n {
            if mask & (1 << i) != 0 {
                v.push(12 + floating[i]);
            } else {
                v.push(12 - floating[i]);
            }
        }
        v.sort();
        let v0 = v[0];
        v.push(v0);

        let mut s = 24;
        for i in 0..(v.len() - 1) {
            let d = (v[i + 1] + 24 - v[i]) % 24;
            let d = cmp::min(d, 24 - d);
            s = cmp::min(s, d);
        }
        ans = cmp::max(ans, s);
    }

    println!("{}", ans);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

