use input::*;
use std::cmp;

fn calc_ans(n: &mut Vec<usize>) -> usize {
    n.sort();
    let mut ans = 24 - n[n.len() - 1];
    for i in 1..n.len() - 1 {
        ans = cmp::min(ans, n[i] - n[i - 1]);
        ans = cmp::min(ans, n[i + 1] - n[i]);
    }
    ans
}
fn calc_subarray(n: &mut Vec<usize>) -> Vec<usize> {
    n.sort();
    let mut v = Vec::new();
    for z in 1..n.len() {
        v.push(n[z] - n[z - 1]);
    }
    v.push(24 - n[n.len() - 1]);
    v
}

fn main() {
    let n: usize;
    input!(n);
    let mut v = input_vector::<usize>();

    if let Some(_) = v.iter().position(|&x| x == 0) {
        p(0);
        return;
    }

    v.push(0);

    let mut ans = calc_ans(&mut v);

    loop {
        v.sort();
        let sub = calc_subarray(&mut v);
        let minindex = sub
            .iter()
            .position(|x| x == sub.iter().min().unwrap())
            .unwrap();

        if minindex + 1 == v.len() {
            v[minindex] = 24 - v[minindex];
        } else if minindex == 0 {
            v[minindex + 1] = 24 - v[minindex + 1];
        } else {
            if minindex + 2 == v.len()
                || v[minindex + 1] - v[minindex - 1] > v[minindex + 2] - v[minindex]
            {
                v[minindex] = 24 - v[minindex];
            } else {
                v[minindex + 1] = 24 - v[minindex + 1];
            }
        }
        if calc_ans(&mut v) <= ans {
            break;
        }
        ans = calc_ans(&mut v);
    }

    p(ans);
}

