fn main() {
    let N: usize = read();
    use std::collections::HashMap;
    let mut map: HashMap<usize, usize> = HashMap::new();
    map.insert(0, 1);
    for _ in 0..N {
        let entry = map.entry(read()).or_insert(0);
        *entry += 1;
        if *entry >= 3 {
            println!("0");
            return;
        }
    }
    let mut vec: Vec<(usize, usize)> = vec![];
    for v in map {
        vec.push(v);
    }
    let mins = dfs(0, &vec, vec![]);
    println!("{}", mins.iter().max().unwrap());
}

fn dfs(depth: usize, vec: &[(usize, usize)], now_times: Vec<usize>) -> Vec<usize> {
    if depth == vec.len() {
        let mut now_times = now_times;
        now_times.sort();
        now_times.push(24);
        let min = now_times
            .windows(2)
            .fold(1000, |acc, v| std::cmp::min(acc, (v[1] - v[0]) % 24));
        return vec![min];
    }
    let v = vec[depth].0;
    let count = vec[depth].1;
    if count == 2 {
        let mut now_times = now_times;
        now_times.push(v);
        now_times.push(24 - v);
        dfs(depth + 1, vec, now_times)
    } else {
        let mut now_times_mut = now_times.clone();
        now_times_mut.push(v);
        let mins1 = dfs(depth + 1, vec, now_times_mut);
        let mut now_times_mut = now_times;
        now_times_mut.push(24 - v);
        let mins2 = dfs(depth + 1, vec, now_times_mut);
        [mins1, mins2].concat()
    }
}

