        let s = s.trim_right().to_owned();
        s.split_whitespace().map(|x| x.parse().unwrap()).collect()
    };

    let mut counts = vec![0; 13];
    counts[0] += 1;
    for x in d {
        counts[x as usize] += 1;
    }

    let mut a = vec![];
    let mut b = vec![];
    for i in 0..13 {
        if counts[i] == 1 {
            a.push(i as isize);
        } else if counts[i] == 2 {
            b.push(i as isize);
        } else if counts[i] >= 3 {
            // answer
            println!("0");
            return;
        }
    }

    let mut v = vec![];
    for x in b {
