    let l = a.len();
    for bits in 0..(1 << l) {
        let mut v = v.clone();
        for (i, x) in a.iter().enumerate() {
            if is_plus(bits, i) {
                v.push(*x);
            } else {
                v.push(24 - *x);
            }
        }

        let tmp = calc_min(&v);
        if max < tmp {
            // debugln!("{}, {:?}", tmp, v);
            max = tmp;
        }
    }

