fn calc_min(v: &Vec<isize>) -> isize {
    let mut min = std::isize::MAX;
    for i in 0..v.len() {
        for j in (i + 1)..v.len() {
            let tmp = calc_diff(v[i], v[j]);
            if tmp < min {
                min = tmp;
            }
        }
    }

    min
}

fn calc_diff(a: isize, b: isize) -> isize {
    std::cmp::min((a - b).abs(), (24 - (a - b).abs()))
}

fn is_plus(bits: isize, index: usize) -> bool {
    (bits & (1 << index)) > 0
}

