    let mut mx = 0;
    for i in 0..1 << n {
        let mut vec = Vec::new();
        vec.push(0);
        for j in 0..n {
            if (i >> j) & 1 == 1 {
                vec.push(d[j]);
            } else {
                vec.push(24 - d[j]);
            }
        }
        vec.sort();
        let mut mn = std::usize::MAX;
        for i in 0..n {
            mn = min!(mn, vec[i + 1] - vec[i]);
        }
