macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n = parse!(it);
    let mut d: Vec<usize> = parse!(it, n);
    d.push(0);
    let mut ret = std::usize::MAX;
    let diff = |x, y| if x > y { x - y } else { y - x };
    let cut = |x| if x > 12 { 24 - x } else { x };
    for i in 0..d.len() {
        for j in 0..d.len() {
            if i == j {
                continue;
            }
            ret = min(ret, max(cut(diff(d[i], d[j])), cut(d[i] + d[j])))
        }
    }
    println!("{}", ret);
}

