    for v in data {
        dt[v as usize] += 1;
    }
    if dt[0] >= 1 || dt[12] >= 2 {
        println!("0");
        return;
    }
    for &x in &dt {
        if x >= 3 {
            println!("0");
            return;
        }
    }

    let mut ans = 0;
    for i in 0..(1 << 11) {
        let mut dd = [false; 24];
        dd[0] = true;
        for (x, &y) in dt.iter().enumerate() {
            if y == 1 && (x == 0 || x == 12) {
                dd[x] = true;
            } else if y == 2 {
                dd[x] = true;
                dd[24 - x] = true;
            } else if y == 1 {
                if (i >> (x - 1)) & 1 != 0 {
                    dd[x] = true;
                } else {
                    dd[24 - x] = true;
                }
            }
        }

        let mut start: i32 = -1;
        let mut last: i32 = -1;
        let mut min_gap: i32 = 24;
        for (x, &y) in dd.iter().enumerate() {
            if !y {
                continue;
            }
            if start == -1 {
                start = x as i32;
            } else {
                min_gap = i32::min(min_gap, x as i32 - last);
            }
            last = x as i32;
        }
        min_gap = i32::min(min_gap, (start + 24) - last);
        ans = i32::max(ans, min_gap);
    }

