        self.iter.peek()
    }
}

const INF: i64 = 1 << 60;

fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin.bytes().map(|c| c.unwrap() as char));
    let N: usize = sc.get();
    let D: Vec<i64> = sc.vec(N);
    let mut s = BTreeSet::new();
    s.insert(D[0]);
    for i in 1..N {
        let mut diff1 = INF;
        for n in D[i]..24+1 {
            if s.contains(&n) {
                diff1 = min(diff1, (n - D[i]).abs());
                break;
            }
        }
        for n in 0..D[i]{
            if s.contains(&n) {
                diff1 = min(diff1, (n - D[i]).abs());
                break;
            }
        }
        let mut diff2 = INF;
        for n in (24-D[i])..24+1 {
            if s.contains(&n) {
                diff2 = min(diff2, (n - (24-D[i])).abs());
                break;
            }
        }
        for n in 0..(24-D[i]) {
            if s.contains(&n) {
                diff2 = min(diff2, (n - (24-D[i])).abs());
                break;
            }
        }
        if diff1 > diff2 {
            s.insert(D[i]);
        } else {
            s.insert(24-D[i]);
        }
    }
