        for n in (0..D[i]).rev() {
            if s.contains(&n) {
                diff1 = min(diff1, (n - D[i]).abs());
                break;
            }
        }
        let mut diff2 = INF;
        for n in (24-D[i])..24+1 {
            if s.contains(&n) {
                diff2 = min(diff2, (n - (24-D[i])).abs());
                break;
            }
        }
        for n in (0..(24-D[i])).rev() {
            if s.contains(&n) {
                diff2 = min(diff2, (n - (24-D[i])).abs());
                break;
            }
        }
        if diff1 > diff2 {
            s.insert(D[i]);
        } else {
            s.insert(24-D[i]);
        }
    }
    s.remove(&0);
    s.remove(&24);
    let mut ans = *D.iter().min().unwrap();
    let mut prev = 0;
    for &si in &s {
        ans = min(ans, (si - prev).abs());
        prev = si;
    }
    println!("{}", ans);
}

